const DAILY_PUJA: CuratedOccasion = {
  intro: {
    hi: 'नित्य पूजा सनातन गृहस्थ का प्रतिदिन का धर्म है — घर के पूजा-स्थान (देवघर) में स्नान-शुद्धि के बाद दीप जलाकर, पंचदेव व अपने इष्ट-देव का श्रद्धापूर्वक पूजन, धूप-नैवेद्य अर्पण, आरती व परिक्रमा। यह कोई भव्य आयोजन नहीं, बल्कि मन को शांत, अनुशासित व ईश्वर-केंद्रित रखने वाली दैनिक साधना है। शास्त्र कहते हैं कि नित्य पूजा से घर में सकारात्मक ऊर्जा, आरोग्य, एकता व दैवी कृपा का स्थायी वास होता है।',
    en: 'Nitya Puja is the daily dharma of the Sanatana householder — after a bath and purification, one lights a lamp at the home shrine (devghar) and reverently worships the Panchdev and one\'s Ishta-devata, offering incense and naivedya, then aarti and circumambulation. It is not a grand event but a daily sadhana that keeps the mind calm, disciplined and God-centred. The shastras say that daily puja establishes lasting positive energy, health, unity and divine grace in the home.',
  },
  significance: [
    { hi: 'नित्य पूजा पंच महायज्ञों में "देव-यज्ञ" है — गृहस्थ का प्रतिदिन का अनिवार्य कर्तव्य, जो मन को अनुशासन व कृतज्ञता सिखाता है।', en: 'Daily puja is the "Deva-yajna" of the five Mahayajnas — the householder\'s daily duty, teaching the mind discipline and gratitude.' },
    { hi: 'पंचदेव (गणेश, विष्णु, शिव, सूर्य, देवी) का संयुक्त पूजन सभी दैवी शक्तियों का संतुलित आशीर्वाद देता है।', en: 'Worshipping the Panchdev (Ganesha, Vishnu, Shiva, Surya, Devi) together brings a balanced blessing of all the divine powers.' },
    { hi: 'नियमित दीप, धूप व मंत्र से घर का वातावरण शुद्ध होकर सकारात्मक तरंगों से भर जाता है, जिससे मानसिक शांति मिलती है।', en: 'Regular lamp, incense and mantra purify the home\'s atmosphere and fill it with positive vibrations, bringing peace of mind.' },
    { hi: 'प्रातः ब्रह्म मुहूर्त में की गई पूजा दिन को शुभ दिशा देती है व एकाग्रता, स्मृति व आरोग्य बढ़ाती है।', en: 'Puja done at dawn in Brahma muhurta sets an auspicious tone for the day and enhances focus, memory and health.' },
    { hi: 'नित्य पूजा से परिवार में श्रद्धा, संस्कार व एकता की परंपरा अगली पीढ़ी तक स्वाभाविक रूप से पहुँचती है।', en: 'Daily puja naturally passes on faith, sanskaras and family unity to the next generation.' },
  ],
  history: {
    hi: 'नित्य पूजा की जड़ें वैदिक "पंच महायज्ञ" व अग्निहोत्र परंपरा में हैं। स्मृति-ग्रंथों (मनुस्मृति, गृह्यसूत्र) में गृहस्थ के लिए प्रतिदिन देव-पूजन, संध्या-वंदन व नैवेद्य का विधान है। कालांतर में यही पूजा घर के देवघर में मूर्ति/चित्र पूजन के रूप में शोडशोपचार व पंचोपचार पद्धति में ढल गई।',
    en: 'Daily puja is rooted in the Vedic "Pancha Mahayajna" and the Agnihotra tradition. The smriti texts (Manusmriti, Grihyasutras) prescribe daily deva-puja, sandhya-vandana and naivedya for the householder. Over time this settled into the worship of idols/images at the home shrine, in the Shodashopachara and Panchopachara methods.',
  },
  muhurat: {
    hi: 'नित्य पूजा का श्रेष्ठ समय ब्रह्म मुहूर्त है (सूर्योदय से ~1.5 घंटे पूर्व, लगभग प्रातः 4:30–6:00) — तब वातावरण शुद्ध व शांत होता है। पूजा में साधक का मुख पूर्व (सूर्योदय की ओर) या उत्तर दिशा में रहे; देव-मूर्ति पूर्व या पश्चिम की ओर मुख किए स्थापित करें। संध्या-काल (सूर्यास्त) भी दीप-आरती हेतु शुभ है।',
    en: 'The best time for daily puja is Brahma muhurta (about 1.5 hours before sunrise, roughly 4:30–6:00 am) — when the air is pure and still. The worshipper should face east (toward the sunrise) or north; place the deity facing east or west. Sandhya (dusk/sunset) is also auspicious for the lamp and aarti.',
  },
  muhuratKey: 'puja',
  shubhMonths: { hi: 'नित्य पूजा प्रतिदिन की जाती है — कोई मास वर्जित नहीं। श्रेष्ठ समय: ब्रह्म मुहूर्त (प्रातः) व संध्या-काल (सूर्यास्त)। शोडशोपचार पूजा आदर्श रूप से प्रातः, दोपहर व संध्या — तीन बार की जा सकती है।', en: 'Daily puja is done every day — no month is forbidden. Best times: Brahma muhurta (dawn) and sandhya (dusk). Shodashopachara puja may ideally be done thrice — morning, noon and evening.' },
  varjit: { hi: 'सूतक/अशौच (जन्म-मृत्यु के सूतक) के दिनों में मूर्ति-स्पर्श व नित्य पूजा स्थगित रहती है — तब केवल मानसिक स्मरण/नाम-जप किया जाता है। रजस्वला व अस्वच्छ अवस्था में देव-स्पर्श वर्जित माना जाता है।', en: 'On days of sutak/ashaucha (birth or death impurity) touching the idol and daily puja are suspended — only mental remembrance/name-japa is done. Touching the deity in an unclean state is traditionally avoided.' },
  nakshatra: { hi: 'दिन के श्रेष्ठ काल: (1) ब्रह्म मुहूर्त — ध्यान व मंत्र-जप हेतु सर्वोत्तम, (2) प्रातः स्नानोपरांत — मुख्य पूजा, (3) संध्या-काल — दीप-आरती व संध्या-वंदन। राहुकाल में नई साधना आरंभ न करें, पर नित्य पूजा व नाम-जप सदैव किए जा सकते हैं।', en: 'Best parts of the day: (1) Brahma muhurta — best for meditation and japa, (2) after the morning bath — the main puja, (3) sandhya — the lamp, aarti and evening prayer. Avoid starting new sadhana in Rahukaal, but daily puja and name-japa may always be done.' },
  tithi: { hi: 'दिशा-नियम: साधक पूर्व या उत्तर की ओर मुख करे; धन-प्रार्थना में उत्तर, विद्या-मोक्ष में पूर्व श्रेष्ठ। दक्षिण की ओर मुख कर पूजा न करें (वह पितृ-दिशा है)। देव-मूर्ति पूर्व/पश्चिमाभिमुख रखें, दीपक देव के दाहिनी ओर।', en: 'Direction rules: face east or north; north for wealth-prayers, east for knowledge/moksha. Do not face south while worshipping (it is the pitri direction). Keep the deity facing east/west, and the lamp to the deity\'s right.' },
  regional: [
    { region: { hi: 'उत्तर भारत', en: 'North India' }, text: { hi: 'देवघर में गणेश-लक्ष्मी, राम-सीता, हनुमान, शिव-परिवार व इष्ट-देव; प्रातः स्नान कर दीप-धूप, जल-अर्पण, तुलसी-पूजन व आरती। तुलसी में जल व संध्या-दीप की परंपरा घर-घर में है।', en: 'The home shrine holds Ganesh-Lakshmi, Ram-Sita, Hanuman, the Shiva family and the Ishta-devata; after a morning bath, lamp-incense, water-offering, tulsi-puja and aarti. Watering the tulsi and a dusk-lamp are near-universal.' } },
    { region: { hi: 'दक्षिण भारत', en: 'South India' }, text: { hi: 'दीप-आराधना प्रधान — कुत्तुविलक्कु (पीतल-दीप) प्रज्वलन, कोलम, तथा प्रातः-संध्या दीप। पंचायतन पूजा (इष्ट-देव केंद्र में, चार अन्य कोनों में) व नैवेद्य-पायसम की परंपरा।', en: 'Lamp-worship is central — lighting the kuttuvilakku (brass lamp), a kolam, and morning-evening lamps. The Panchayatana puja (Ishta-devata in the centre, four others at the corners) and naivedyam-payasam are customary.' } },
    { region: { hi: 'महाराष्ट्र', en: 'Maharashtra' }, text: { hi: 'देव्हारा (देवघर) में गणपति, विठोबा, अन्नपूर्णा व कुलदैवत; प्रातः स्नान कर देवपूजा, तुलसी-वृंदावन पूजन व संध्या-दीप। "शुभं करोति" श्लोक संध्या-दीप के समय बच्चों संग बोला जाता है।', en: 'The devhara holds Ganpati, Vithoba, Annapurna and the kuladaivat; after a bath, deva-puja, worship of the tulsi-vrindavan and a dusk-lamp. The "Shubham Karoti" shloka is recited with children at the evening lamp.' } },
    { region: { hi: 'बंगाल व पूर्वी भारत', en: 'Bengal & East India' }, text: { hi: 'नित्य पूजा में शालग्राम/गोपाल-सेवा, दुर्गा व कुल-देवता; शंख-ध्वनि, उलू-ध्वनि व धूप-धुनुची, तुलसी-मंच पर संध्या-दीप। भोग-नैवेद्य के बिना पूजा अपूर्ण मानी जाती है।', en: 'Daily puja includes Shaligram/Gopal-seva, Durga and the family deity; conch and ululation, dhoop-dhunuchi, and a dusk-lamp at the tulsi-mancha. Puja is deemed incomplete without a bhog-naivedya.' } },
  ],
  preparation: [
    { hi: 'ब्रह्म मुहूर्त में उठकर स्नान करें व स्वच्छ, धुले (यथासंभव सिले-बिना/सूती) वस्त्र पहनें; तन-मन की शुद्धि पूजा की प्रथम शर्त है।', en: 'Rise in Brahma muhurta, bathe and wear clean, washed (ideally cotton/unstitched) clothes; purity of body and mind is the first condition of puja.' },
    { hi: 'देवघर व मूर्ति/चित्रों की सफाई कर गंगाजल छिड़कें; बासी फूल हटाकर ताज़े पुष्प, जल व सामग्री रखें।', en: 'Clean the shrine and idols/images, sprinkle Ganga-jal; remove stale flowers and set fresh flowers, water and materials.' },
    { hi: 'आसन (ऊनी/कुशा) बिछाकर पूर्व या उत्तर की ओर मुख कर बैठें; दीप, धूप, जल-पात्र, अक्षत, पुष्प व नैवेद्य पास रखें।', en: 'Spread an asana (wool/kusha), sit facing east or north; keep the lamp, incense, water-pot, akshat, flowers and naivedya at hand.' },
    { hi: 'हाथ में जल लेकर आचमन कर स्वयं को शुद्ध करें; करदर्शन व भूमि-वंदन कर दिन का आरंभ करें।', en: 'Do achaman with water in the hand to purify yourself; begin the day with kar-darshan and bhumi-vandana (saluting the earth).' },
  ],
  samagri: [
    { name: { hi: 'देवघर व पंचदेव/इष्ट-देव मूर्ति-चित्र', en: 'Shrine & Panchdev/Ishta-devata idol-image' }, reason: { hi: 'नित्य पूजा का केंद्र — गणेश, विष्णु, शिव, सूर्य व देवी सहित इष्ट-देव।', en: 'The centre of daily puja — Ganesha, Vishnu, Shiva, Surya and Devi with the Ishta-devata.' } },
    { name: { hi: 'घी/तेल का दीपक व बाती', en: 'Ghee/oil lamp & wick' }, reason: { hi: 'दीप प्रज्वलन = ज्ञान व मंगल; पूजा का अनिवार्य अंग।', en: 'Lighting the lamp = knowledge and auspiciousness; an essential of puja.' } },
    { name: { hi: 'धूप/अगरबत्ती व कपूर', en: 'Dhoop/incense & camphor' }, reason: { hi: 'सुगंध व शुद्ध वातावरण; धूप-अर्पण व आरती हेतु।', en: 'For fragrance, a pure atmosphere, the dhoop-offering and aarti.' } },
    { name: { hi: 'जल-पात्र, आचमनी व पंचपात्र', en: 'Water-pot, achamani & panchapatra' }, reason: { hi: 'आचमन, अर्घ्य व देव-स्नान (अभिषेक) हेतु।', en: 'For achaman, arghya and bathing the deity (abhishek).' } },
    { name: { hi: 'रोली/कुमकुम, चंदन, हल्दी व अक्षत', en: 'Roli/kumkum, sandal, haldi & akshat' }, reason: { hi: 'तिलक व देव-अर्पण; अखंड चावल पूर्णता का प्रतीक।', en: 'For tilak and offerings; unbroken rice symbolises wholeness.' } },
    { name: { hi: 'ताज़े पुष्प, माला व दूर्वा', en: 'Fresh flowers, garland & durva' }, reason: { hi: 'देव-अर्पण; गणेश को दूर्वा व विष्णु को तुलसी प्रिय।', en: 'For offerings; durva is dear to Ganesha and tulsi to Vishnu.' } },
    { name: { hi: 'तुलसी-दल', en: 'Tulsi leaves' }, reason: { hi: 'विष्णु/कृष्ण पूजन में अनिवार्य; बिना तुलसी नैवेद्य अपूर्ण माना जाता है।', en: 'Essential in Vishnu/Krishna worship; naivedya is deemed incomplete without tulsi.' } },
    { name: { hi: 'नैवेद्य (फल, मिठाई, पंचामृत/मिश्री)', en: 'Naivedya (fruit, sweet, panchamrit/mishri)' }, reason: { hi: 'भोग-अर्पण — भक्ति व कृतज्ञता का प्रतीक; बाद में प्रसाद रूप में ग्रहण।', en: 'The bhog-offering — a symbol of devotion and gratitude; later taken as prasad.' } },
    { name: { hi: 'घंटी (घंटा)', en: 'Bell (ghanta)' }, reason: { hi: 'आवाहन व आरती में नाद — नकारात्मकता दूर कर देव-आगमन का सूचक।', en: 'Its sound during invocation and aarti clears negativity and heralds the deity.' } },
    { name: { hi: 'शंख', en: 'Conch (shankh)' }, reason: { hi: 'पूजा-आरंभ व आरती में शंखनाद; पवित्रता व मंगल का प्रतीक।', en: 'The conch-blow at the start and during aarti; a symbol of purity and auspiciousness.' } },
    { name: { hi: 'आसन (ऊनी/कुशा) व वस्त्र', en: 'Asana (wool/kusha) & cloth' }, reason: { hi: 'साधक के बैठने हेतु शुद्ध आसन — ऊर्जा-स्थिरता का आधार।', en: 'A pure seat for the worshipper — the basis of steady energy.' } },
    { name: { hi: 'गंगाजल', en: 'Ganga-jal' }, reason: { hi: 'सर्वोच्च शुद्धिकारक; छिड़काव, आचमन व अभिषेक में।', en: 'The supreme purifier; for sprinkling, achaman and abhishek.' } },
    { name: { hi: 'माला (तुलसी/रुद्राक्ष/स्फटिक)', en: 'Japa mala (tulsi/rudraksha/crystal)' }, reason: { hi: 'नाम-जप व मंत्र-गणना हेतु — इष्ट-देव के अनुसार माला चुनें।', en: 'For name-japa and counting mantras — choose the mala per the Ishta-devata.' } },
    { name: { hi: 'कपूर-आरती पात्र व माचिस', en: 'Camphor-aarti holder & matches' }, reason: { hi: 'आरती में कपूर/दीप घुमाने हेतु।', en: 'For circling camphor/lamp during the aarti.' } },
  ],
  steps: [
    { title: { hi: 'स्नान, शुद्धि व करदर्शन', en: 'Bath, Purification & Kar-darshan' }, what: { hi: 'ब्रह्म मुहूर्त में उठकर स्नान करें; जागते ही हथेलियों का दर्शन (करदर्शन) कर व भूमि-वंदन कर दिन आरंभ करें, स्वच्छ वस्त्र पहनें।', en: 'Rise in Brahma muhurta and bathe; on waking, behold your palms (kar-darshan) and salute the earth (bhumi-vandana), then wear clean clothes.' }, why: { hi: 'तन-मन की शुद्धि व कृतज्ञ भाव पूजा की प्रथम शर्त है।', en: 'Purity of body-mind and a grateful attitude are the first condition of puja.' } },
    { title: { hi: 'आसन, आचमन व प्राणायाम', en: 'Asana, Achaman & Pranayama' }, what: { hi: 'पूर्व/उत्तर की ओर मुख कर आसन पर बैठें; तीन बार आचमन कर व कुछ दीर्घ श्वास (प्राणायाम) लेकर मन को स्थिर करें।', en: 'Sit on the asana facing east/north; do achaman thrice and take a few deep breaths (pranayama) to steady the mind.' }, why: { hi: 'शरीर व मन की स्थिरता से ही ध्यान व पूजा फलदायी होती है।', en: 'Only a steady body and mind make meditation and puja fruitful.' } },
    { title: { hi: 'दीप प्रज्वलन व घंटी-शंख', en: 'Light the Lamp & Bell-Conch' }, what: { hi: 'देव के दाहिनी ओर घी/तेल का दीप जलाएँ, धूप जलाएँ; शंख व घंटी बजाकर देव-आवाहन करें।', en: 'Light the ghee/oil lamp to the deity\'s right and the incense; blow the conch and ring the bell to invoke the deity.' }, why: { hi: 'दीप-नाद वातावरण को शुद्ध कर देवता के आगमन का मंगल-सूचक है।', en: 'The lamp and sound purify the space and auspiciously herald the deity.' } },
    { title: { hi: 'संकल्प व गणेश-स्मरण', en: 'Sankalp & Ganesha remembrance' }, what: { hi: 'हाथ में जल-अक्षत लेकर नित्य पूजा का संकल्प लें; सर्वप्रथम विघ्नहर्ता श्री गणेश का स्मरण-पूजन करें।', en: 'Take water and akshat in hand for the daily-puja sankalp; first remember and worship Ganesha, the remover of obstacles.' }, why: { hi: 'हर पूजा निर्विघ्न पूर्ण हो — इसलिए गणेश प्रथम-पूज्य हैं।', en: 'So the puja completes without obstacles — hence Ganesha is worshipped first.' }, deity: { hi: 'श्री गणेश', en: 'Lord Ganesha' } },
    { title: { hi: 'देव-आवाहन व स्नान (अभिषेक)', en: 'Invocation & Bathing (Abhishek)' }, what: { hi: 'पंचदेव व इष्ट-देव का आवाहन कर, मूर्ति को जल/पंचामृत से स्नान कराएँ, स्वच्छ कर आसन पर पुनः स्थापित करें।', en: 'Invoke the Panchdev and Ishta-devata, bathe the idol with water/panchamrit, wipe it clean and reseat it.' }, why: { hi: 'देव-स्नान अतिथि-सत्कार का प्रथम उपचार है (शोडशोपचार का अंग)।', en: 'Bathing the deity is the first act of hospitality (part of the sixteen upacharas).' }, deity: { hi: 'पंचदेव व इष्ट-देव', en: 'Panchdev & Ishta-devata' } },
    { title: { hi: 'वस्त्र, चंदन, अक्षत व पुष्प', en: 'Cloth, Sandal, Akshat & Flowers' }, what: { hi: 'देव को वस्त्र/जनेऊ, चंदन-तिलक, अक्षत, पुष्प-माला व (विष्णु हेतु) तुलसी-दल अर्पित करें।', en: 'Offer the deity cloth/sacred thread, sandal-tilak, akshat, a flower garland and (for Vishnu) tulsi leaves.' }, why: { hi: 'ये उपचार स्पर्श व दृष्टि इंद्रियों से देव-सेवा के प्रतीक हैं।', en: 'These upacharas are acts of service through the senses of touch and sight.' } },
    { title: { hi: 'धूप, दीप व नैवेद्य', en: 'Dhoop, Deep & Naivedya' }, what: { hi: 'धूप-दीप दिखाकर देव को फल, मिठाई या पंचामृत का नैवेद्य अर्पित करें; जल से आचमन कराएँ।', en: 'Show the incense and lamp, then offer the deity fruit, sweet or panchamrit as naivedya; offer water for achaman.' }, why: { hi: 'गंध (धूप), दृष्टि (दीप) व स्वाद (नैवेद्य) — पंचोपचार के मुख्य अंग; भक्ति का समर्पण।', en: 'Smell (dhoop), sight (deep) and taste (naivedya) — the core of the pancha-upachara; an offering of devotion.' } },
    { title: { hi: 'मंत्र-जप व ध्यान', en: 'Mantra-japa & Meditation' }, what: { hi: 'माला लेकर इष्ट-देव के मूल-मंत्र या गायत्री का 108 बार जप करें; कुछ क्षण ध्यान में स्थिर रहें।', en: 'With the mala, chant the Ishta-devata\'s root mantra or the Gayatri 108 times; rest a while in meditation.' }, why: { hi: 'जप व ध्यान मन को एकाग्र कर देव से आंतरिक संबंध जोड़ते हैं।', en: 'Japa and meditation focus the mind and forge an inner bond with the deity.' } },
    { title: { hi: 'आरती व पुष्पांजलि', en: 'Aarti & Pushpanjali' }, what: { hi: 'घंटी बजाते हुए कपूर/दीप से आरती उतारें; अंत में पुष्पांजलि (पुष्प समर्पण) अर्पित करें।', en: 'Ring the bell and perform aarti with camphor/lamp; conclude with pushpanjali (offering of flowers).' }, why: { hi: 'आरती पूजा की पूर्णाहुति है — प्रकाश व श्रद्धा का समर्पण।', en: 'The aarti seals the puja — an offering of light and devotion.' } },
    { title: { hi: 'प्रदक्षिणा, प्रणाम व क्षमा-प्रार्थना', en: 'Pradakshina, Pranam & Kshama-prarthana' }, what: { hi: 'देव की परिक्रमा (प्रदक्षिणा) कर साष्टांग प्रणाम करें; पूजा में हुई भूल-चूक हेतु क्षमा-प्रार्थना कर प्रसाद ग्रहण करें व वितरित करें।', en: 'Circumambulate the deity (pradakshina) and prostrate; ask forgiveness (kshama-prarthana) for any lapses, then take and share the prasad.' }, why: { hi: 'प्रदक्षिणा समर्पण का व क्षमा-प्रार्थना विनम्रता का भाव है, जो पूजा को पूर्ण करता है।', en: 'Pradakshina expresses surrender and kshama-prarthana humility, completing the puja.' } },
  ],
  mantras: [
    { title: { hi: 'करदर्शन (प्रातः जागरण)', en: 'Kar-darshan (on waking)' }, sanskrit: 'कराग्रे वसते लक्ष्मीः करमध्ये सरस्वती।\nकरमूले तु गोविन्दः प्रभाते करदर्शनम्॥', roman: 'Karagre vasate Lakshmih kara-madhye Saraswati.\nKara-mule tu Govindah prabhate kara-darshanam.', meaning: { hi: 'हाथ के अग्र भाग में लक्ष्मी, मध्य में सरस्वती व मूल में गोविन्द (विष्णु) का वास है; इसलिए प्रातः जागते ही अपनी हथेलियों का दर्शन करें।', en: 'Lakshmi dwells at the fingertips, Saraswati in the palm\'s middle, and Govinda (Vishnu) at its base; so on waking, first behold your palms.' }, when: { hi: 'प्रातः निद्रा-त्याग के तुरंत बाद', en: 'Right after waking from sleep' } },
    { title: { hi: 'गणेश वंदना', en: 'Ganesha Vandana' }, sanskrit: 'वक्रतुण्ड महाकाय सूर्यकोटि समप्रभ।\nनिर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥\nॐ गं गणपतये नमः॥', roman: 'Vakratunda Mahakaya Suryakoti Samaprabha.\nNirvighnam kuru me deva sarvakaryeshu sarvada.\nOm Gam Ganapataye Namah.', meaning: { hi: 'हे वक्रतुंड, महाकाय, करोड़ों सूर्य के समान तेजस्वी देव! मेरे सभी कार्य सदा निर्विघ्न पूर्ण करें।', en: 'O curved-trunk, mighty, radiant as a million suns — O Lord, make all my tasks ever free of obstacles.' }, when: { hi: 'पूजा के आरंभ में, प्रथम-पूज्य गणेश हेतु', en: 'At the start of the puja, for the first-worshipped Ganesha' }, count: '3 / 11' },
    { title: { hi: 'गायत्री महामंत्र', en: 'Gayatri Mahamantra' }, sanskrit: 'ॐ भूर्भुवः स्वः तत्सवितुर्वरेण्यं\nभर्गो देवस्य धीमहि धियो यो नः प्रचोदयात्॥', roman: 'Om bhur bhuvah svah tat savitur varenyam\nbhargo devasya dhimahi dhiyo yo nah prachodayat.', meaning: { hi: 'उस सविता (सूर्य) देव के श्रेष्ठ तेज का हम ध्यान करते हैं, जो हमारी बुद्धि को सन्मार्ग की ओर प्रेरित करें।', en: 'We meditate on the supreme radiance of Savitr (the Sun); may it inspire our intellect toward righteousness.' }, when: { hi: 'ब्रह्म मुहूर्त में — सूर्य-अर्घ्य व ध्यान में जप', en: 'In Brahma muhurta — during Surya-arghya and meditation' }, count: '3 / 11 / 108' },
    { title: { hi: 'पंचदेव / देव-आवाहन ध्यान', en: 'Panchdev / Invocation dhyana' }, sanskrit: 'आदित्यं गणनाथं च देवीं रुद्रं च केशवम्।\nपञ्च दैवत्यमित्युक्तं सर्वकर्मसु पूजयेत्॥', roman: 'Adityam Gananatham cha Devim Rudram cha Keshavam.\nPancha daivatyam ityuktam sarva-karmasu pujayet.', meaning: { hi: 'सूर्य (आदित्य), गणेश (गणनाथ), देवी, शिव (रुद्र) व विष्णु (केशव) — ये पंचदेव कहे गए हैं; सभी शुभ कर्मों में इनका पूजन करना चाहिए।', en: 'Surya (Aditya), Ganesha, Devi, Shiva (Rudra) and Vishnu (Keshava) — these are called the Panchdev; they should be worshipped in all auspicious rites.' }, when: { hi: 'देव-आवाहन के समय', en: 'While invoking the deities' } },
    { title: { hi: 'नैवेद्य-समर्पण मंत्र', en: 'Naivedya-offering mantra' }, sanskrit: 'ॐ प्राणाय स्वाहा, ॐ अपानाय स्वाहा, ॐ व्यानाय स्वाहा।\nॐ उदानाय स्वाहा, ॐ समानाय स्वाहा॥', roman: 'Om Pranaya svaha, Om Apanaya svaha, Om Vyanaya svaha.\nOm Udanaya svaha, Om Samanaya svaha.', meaning: { hi: 'हे देव! यह नैवेद्य पाँचों प्राणों (प्राण, अपान, व्यान, उदान, समान) को समर्पित है — कृपया स्वीकार करें।', en: 'O Lord, this naivedya is offered to the five vital breaths (prana, apana, vyana, udana, samana) — please accept it.' }, when: { hi: 'देव को भोग/नैवेद्य अर्पित करते समय', en: 'While offering bhog/naivedya to the deity' } },
    { title: { hi: 'क्षमा-प्रार्थना', en: 'Kshama-prarthana (asking forgiveness)' }, sanskrit: 'आवाहनं न जानामि न जानामि विसर्जनम्।\nपूजां चैव न जानामि क्षम्यतां परमेश्वर॥', roman: 'Avahanam na janami na janami visarjanam.\nPujam chaiva na janami kshamyatam Parameshvara.', meaning: { hi: 'हे परमेश्वर! मैं न आवाहन जानता हूँ, न विसर्जन, न ही पूजा की पूर्ण विधि — मेरी भूलों को क्षमा करें।', en: 'O Supreme Lord, I know neither the invocation nor the farewell, nor the full method of puja — forgive my lapses.' }, when: { hi: 'पूजा के अंत में, विसर्जन से पूर्व', en: 'At the end of the puja, before visarjan' } },
  ],
  aartis: [
    { title: { hi: 'ॐ जय जगदीश हरे', en: 'Om Jai Jagdish Hare' }, lines: 'ॐ जय जगदीश हरे, स्वामी जय जगदीश हरे।\nभक्त जनों के संकट, क्षण में दूर करे॥\n(पंचदेव व इष्ट-देव की सामान्य आरती — परिवार सहित गाएँ।)' },
    { title: { hi: 'शुभं करोति (संध्या-दीप)', en: 'Shubham Karoti (evening lamp)' }, lines: 'शुभं करोति कल्याणम् आरोग्यं धनसम्पदा।\nशत्रुबुद्धिविनाशाय दीपज्योतिर्नमोऽस्तु ते॥\n(संध्या-काल दीप जलाते समय, विशेषतः बच्चों संग।)' },
  ],
  dos: [
    { hi: 'ब्रह्म मुहूर्त में स्नान कर, स्वच्छ वस्त्र पहन, पूर्व/उत्तर की ओर मुख कर पूजा करें।', en: 'Bathe in Brahma muhurta, wear clean clothes and perform the puja facing east/north.' },
    { hi: 'नित्य पूजा को प्रतिदिन नियम से करें — छोटी हो पर निरंतर हो; निरंतरता ही मुख्य है।', en: 'Do the daily puja regularly — keep it small if needed, but unbroken; consistency matters most.' },
    { hi: 'ताज़े पुष्प, शुद्ध जल व श्रद्धा से भरा मन अर्पित करें; बासी सामग्री हटा दें।', en: 'Offer fresh flowers, pure water and a mind full of devotion; remove stale materials.' },
    { hi: 'नैवेद्य अर्पित कर बाद में उसे प्रसाद रूप में ग्रहण व वितरित करें; दीप संध्या-काल भी जलाएँ।', en: 'Offer naivedya, then take and share it as prasad; light the lamp again at dusk.' },
    { hi: 'पूजा के अंत में क्षमा-प्रार्थना कर विनम्रता से भूल-चूक की क्षमा माँगें।', en: 'End with the kshama-prarthana, humbly asking forgiveness for any lapses.' },
  ],
  donts: [
    { hi: 'अस्नात, अशुद्ध अवस्था या जूठे हाथों से देव-मूर्ति का स्पर्श न करें।', en: 'Do not touch the deity unbathed, impure or with soiled hands.' },
    { hi: 'दक्षिण दिशा की ओर मुख कर पूजा न करें (वह पितृ-दिशा मानी जाती है)।', en: 'Do not face south while worshipping (it is regarded as the pitri direction).' },
    { hi: 'सूतक/अशौच व रजस्वला अवस्था में देव-स्पर्श व नित्य पूजा न करें — केवल मानसिक जप करें।', en: 'Avoid touching the deity and daily puja during sutak/ashaucha and menstruation — do only mental japa.' },
    { hi: 'तुलसी-दल नाखून से न तोड़ें व बासी फूल-जल देव पर न चढ़ाएँ; गणेश को तुलसी अर्पित न करें।', en: 'Do not pluck tulsi with nails or offer stale flowers/water; do not offer tulsi to Ganesha.' },
    { hi: 'पूजा के बीच बातचीत, मोबाइल या क्रोध से मन न भटकाएँ; दीप को फूँक से न बुझाएँ।', en: 'Do not distract the mind with talk, phone or anger mid-puja; do not blow out the lamp.' },
  ],
  mistakes: [
    { hi: 'पूजा को लंबा-भव्य समझकर छोड़ देना — नित्य पूजा का सार निरंतरता है, विस्तार नहीं।', en: 'Skipping puja because it seems long/elaborate — the essence of nitya puja is consistency, not scale.' },
    { hi: 'दीप देव के बाईं ओर रखना या धूप-नैवेद्य का क्रम भूल जाना।', en: 'Placing the lamp to the deity\'s left, or forgetting the dhoop-naivedya sequence.' },
    { hi: 'बासी/मुरझाए फूल व जल हटाए बिना नई पूजा करना।', en: 'Doing a fresh puja without removing the stale flowers and water.' },
    { hi: 'नैवेद्य अर्पित किए बिना ही प्रसाद ग्रहण कर लेना — पहले देव को भोग लगाएँ।', en: 'Eating the prasad before it is offered — first present the bhog to the deity.' },
  ],
  faqs: [
    { q: { hi: 'नित्य पूजा का सबसे अच्छा समय कौन-सा है?', en: 'What is the best time for daily puja?' }, a: { hi: 'ब्रह्म मुहूर्त (सूर्योदय से ~1.5 घंटे पूर्व) श्रेष्ठ है; व्यस्तता में प्रातः स्नान के बाद व संध्या-दीप के समय भी की जा सकती है।', en: 'Brahma muhurta (about 1.5 hrs before sunrise) is best; if busy, it can also be done after the morning bath and at the dusk-lamp.' } },
    { q: { hi: 'शोडशोपचार व पंचोपचार में क्या अंतर है?', en: 'What is the difference between Shodashopachara and Panchopachara?' }, a: { hi: 'शोडशोपचार = 16 उपचार (पूर्ण विधि); पंचोपचार = 5 मुख्य उपचार (गंध, पुष्प, धूप, दीप, नैवेद्य)। समयाभाव में पंचोपचार पर्याप्त है।', en: 'Shodashopachara = 16 offerings (the full method); Panchopachara = 5 core offerings (gandha, pushpa, dhoop, deep, naivedya). When short on time, the panchopachara suffices.' } },
    { q: { hi: 'पूजा में किस दिशा की ओर मुख करें?', en: 'Which direction should I face during puja?' }, a: { hi: 'पूर्व (सूर्योदय) या उत्तर श्रेष्ठ; धन-प्रार्थना में उत्तर, विद्या-मोक्ष में पूर्व। दक्षिण की ओर मुख न करें।', en: 'East (sunrise) or north is best; north for wealth-prayers, east for knowledge/moksha. Do not face south.' } },
    { q: { hi: 'क्या रोज़ स्नान के बिना पूजा कर सकते हैं?', en: 'Can I do puja without bathing daily?' }, a: { hi: 'शारीरिक शुद्धि पूजा की शर्त है; अस्वस्थता या यात्रा में हाथ-पैर धोकर, स्वच्छ होकर मानसिक पूजा व नाम-जप किया जा सकता है।', en: 'Bodily purity is a condition; when ill or travelling, one may wash hands/feet, become clean, and do a mental puja and name-japa.' } },
    { q: { hi: 'यदि पूरी विधि न आती हो तो क्या करें?', en: 'What if I don\'t know the full method?' }, a: { hi: 'श्रद्धा सर्वोपरि है — दीप, धूप, पुष्प, नैवेद्य व नाम-जप के साथ सरल पंचोपचार पूजा करें; अंत में क्षमा-प्रार्थना पढ़ें।', en: 'Devotion matters most — do a simple panchopachara with lamp, incense, flowers, naivedya and name-japa; end with the kshama-prarthana.' } },
    { q: { hi: 'क्या तुलसी हर देव को चढ़ाई जा सकती है?', en: 'Can tulsi be offered to every deity?' }, a: { hi: 'तुलसी विष्णु/कृष्ण को परम प्रिय है, पर गणेश को तुलसी नहीं चढ़ाई जाती; देवी को दूर्वा-तुलसी के स्थान पर पुष्प व अक्षत प्रिय हैं।', en: 'Tulsi is dearest to Vishnu/Krishna, but tulsi is not offered to Ganesha; the Devi prefers flowers and akshat.' } },
  ],
  estTime: { hi: 'संक्षिप्त (पंचोपचार) ~10–15 मिनट · पूर्ण (शोडशोपचार) ~30–45 मिनट', en: 'Short (panchopachara) ~10–15 min · Full (shodashopachara) ~30–45 min' },
  difficulty: { hi: 'सरल · स्वयं करने योग्य', en: 'Easy · self-performed' },
  disclaimer: {
    hi: 'नित्य पूजा की विधि संप्रदाय, इष्ट-देव व कुलाचार अनुसार भिन्न होती है। यहाँ दी गई सामग्री सामान्य वैदिक/शास्त्रीय मार्गदर्शन हेतु है; अपने परिवार की परंपरा, गुरु व योग्य पुरोहित के निर्देशों का पालन सर्वोपरि है।',
    en: 'The method of daily puja varies by sampradaya, Ishta-devata and family lineage (kulachar). This content is general Vedic/shastric guidance; following your family tradition, guru and a qualified purohit\'s guidance is supreme.',
  },
};

/* ─────────────────────────────────────────────────────────────────────────
 * DOSH NIVARAN (दोष निवारण — planetary / graha dosha remedies & shanti)
 * Navagraha shanti + common doshas (Mangal, Kaal Sarp, Pitra, Shani Sade-Sati,
 * Nazar): Navagraha puja, Mahamrityunjaya jaap, graha beej-mantras & daan,
 * rudrabhishek. Cross-referenced: drikpanchang & templepurohit (navagraha
 * beej mantras), varanasipooja (navgrah shanti), astrovidhi (kaal sarp),
 * webdunia (9 daan) + traditional shanti-paddhati. FRAMED AS TRADITIONAL
 * UPAAY — NOT a substitute for medical/legal/financial advice; consult a
 * qualified astrologer/purohit. Kulachar guidance is supreme.
 * ──────────────────────────────────────────────────────────────────────── */
const DOSH_NIVARAN: CuratedOccasion = {
  intro: {
    hi: 'दोष निवारण से तात्पर्य है कुंडली में ग्रहों की प्रतिकूल स्थिति (ग्रह-दोष) से उत्पन्न बाधाओं की शांति हेतु किए जाने वाले पारंपरिक उपाय। ज्योतिष के अनुसार नवग्रह हमारे कर्म-फल के वाहक हैं; जब कोई ग्रह अशुभ या पीड़ित होता है तो जीवन के किसी क्षेत्र में रुकावट अनुभव होती है। नवग्रह शांति पूजा, महामृत्युंजय जप, विशिष्ट ग्रह-मंत्र व दान, तथा रुद्राभिषेक जैसे उपाय ग्रहों को शांत व अनुकूल बनाने हेतु किए जाते हैं। ये उपाय श्रद्धा, धैर्य व सत्कर्म के साथ ही फलदायी माने जाते हैं।',
    en: 'Dosh Nivaran refers to the traditional remedies (upaay) done to pacify the difficulties arising from an unfavourable planetary placement (graha-dosha) in the horoscope. In Jyotish, the nine planets carry the fruits of our karma; when a planet is inauspicious or afflicted, obstruction is felt in some area of life. Remedies such as Navagraha Shanti puja, Mahamrityunjaya jaap, specific graha-mantras and daana, and rudrabhishek are done to calm and favourably dispose the planets. These are held to bear fruit only alongside faith, patience and good conduct.',
  },
  significance: [
    { hi: 'नवग्रह हमारे संचित कर्मों के फल-दाता हैं — शांति-उपाय उनके अशुभ प्रभाव को कम कर मन को धैर्य व सकारात्मकता देते हैं।', en: 'The nine planets dispense the fruits of our accumulated karma — shanti-remedies soften their adverse effects and give the mind patience and positivity.' },
    { hi: 'महामृत्युंजय जप शिव को समर्पित है — यह अकाल-मृत्यु के भय, रोग व मानसिक क्लेश की शांति हेतु सर्वश्रेष्ठ माना गया है।', en: 'The Mahamrityunjaya jaap is dedicated to Shiva — held supreme for pacifying the fear of untimely death, illness and mental distress.' },
    { hi: 'ग्रह-विशेष मंत्र-जप, संबंधित वार का व्रत व दान से पीड़ित ग्रह को "बल" व अनुकूलता मिलती है (जैसे शनि हेतु शनिवार-व्रत व तिल-तेल दान)।', en: 'Chanting a planet\'s mantra, fasting on its weekday and giving its daana strengthens and favourably disposes the afflicted planet (e.g., for Shani, Saturday fast and donation of sesame-oil).' },
    { hi: 'पितृ दोष की शांति से पूर्वजों का आशीर्वाद मिलता है, जो वंश-वृद्धि व पारिवारिक सुख में सहायक माना जाता है।', en: 'Pacifying Pitra Dosha earns the ancestors\' blessings, held to aid the growth and happiness of the family line.' },
    { hi: 'ये उपाय आत्म-अनुशासन, दान व सेवा को प्रोत्साहित करते हैं — जिनका सकारात्मक मनोवैज्ञानिक व सामाजिक प्रभाव भी होता है।', en: 'These remedies encourage self-discipline, charity and service — which also carry a positive psychological and social effect.' },
  ],
  history: {
    hi: 'नवग्रह पूजन की परंपरा वेद व ज्योतिष-शास्त्र में अति प्राचीन है; याज्ञवल्क्य-स्मृति व अनेक शांति-पद्धतियों में ग्रह-शांति का विधान है। महामृत्युंजय मंत्र ऋग्वेद (7.59.12) व यजुर्वेद का "त्र्यम्बक मंत्र" है, जिसे महर्षि मार्कण्डेय व वसिष्ठ से जोड़ा जाता है। ग्रह-दान व शांति-हवन की परंपरा सदियों से भारतीय समाज में प्रचलित है।',
    en: 'Navagraha worship is ancient in the Vedas and Jyotish-shastra; the Yajnavalkya Smriti and many shanti-paddhatis prescribe graha-shanti. The Mahamrityunjaya mantra is the "Tryambaka mantra" of the Rigveda (7.59.12) and Yajurveda, associated with the sages Markandeya and Vasishtha. The tradition of graha-daana and shanti-havan has been current in Indian society for centuries.',
  },
  muhurat: {
    hi: 'ग्रह-शांति उपाय प्रायः संबंधित ग्रह के वार पर आरंभ किए जाते हैं (शनि-शनिवार, मंगल-मंगलवार, गुरु-गुरुवार आदि); महामृत्युंजय व रुद्राभिषेक सोमवार व श्रावण मास में विशेष फलदायी। ग्रहण, अमावस्या व पितृपक्ष पितृ-कर्म हेतु उपयुक्त हैं। सटीक मुहूर्त व उपाय कुंडली-विश्लेषण के बाद योग्य ज्योतिषी/पुरोहित ही निर्धारित करते हैं। नीचे दिए बटन से आप शुभ मुहूर्त इसी ऐप में देख सकते हैं।',
    en: 'Graha-shanti remedies are usually begun on the planet\'s own weekday (Shani–Saturday, Mangal–Tuesday, Guru–Thursday, etc.); Mahamrityunjaya and rudrabhishek are especially fruitful on Mondays and in the month of Shravan. Eclipses, Amavasya and Pitru Paksha suit pitri-rites. The exact muhurat and remedy are fixed by a qualified astrologer/purohit only after analysing the chart. Use the button below to check the muhurat in the app.',
  },
  muhuratKey: 'puja',
  shubhMonths: { hi: 'श्रेष्ठ काल: श्रावण मास (शिव-उपाय, महामृत्युंजय, रुद्राभिषेक), संबंधित ग्रह का वार, तथा शांति-हवन हेतु शुभ तिथि-नक्षत्र। पितृ-दोष उपाय: अमावस्या व पितृपक्ष।', en: 'Best periods: the month of Shravan (Shiva-remedies, Mahamrityunjaya, rudrabhishek), the planet\'s own weekday, and an auspicious tithi-nakshatra for a shanti-havan. Pitra-dosha remedies: Amavasya and Pitru Paksha.' },
  varjit: { hi: 'सामान्यतः रिक्ता तिथि, भद्रा व राहुकाल में नया शांति-अनुष्ठान आरंभ न करें (नित्य जप सदैव किया जा सकता है)। ग्रहण-काल केवल मंत्र-जप हेतु उत्तम है, पर मूर्ति-स्पर्श व भोजन-कार्य वर्जित।', en: 'Generally avoid starting a new shanti-rite in Rikta tithis, Bhadra and Rahukaal (daily japa may always be done). Eclipse time is excellent for mantra-japa only, but touching idols and eating are avoided then.' },
  nakshatra: { hi: 'महामृत्युंजय व मृत्युंजय-हवन हेतु मृगशिरा, आर्द्रा व शिव-संबंधी नक्षत्र शुभ; ग्रह-विशेष उपाय उस ग्रह के नक्षत्र (जैसे शनि हेतु पुष्य/अनुराधा) में विशेष फलदायी।', en: 'For Mahamrityunjaya and mrityunjaya-havan, Mrigashira, Ardra and Shiva-related nakshatras are auspicious; a planet\'s remedy is especially fruitful in that planet\'s nakshatra (e.g., Pushya/Anuradha for Shani).' },
  tithi: { hi: 'शुभ तिथि: द्वितीया, तृतीया, पंचमी, सप्तमी, दशमी, त्रयोदशी (शिव-उपाय हेतु प्रदोष/त्रयोदशी व सोमवार श्रेष्ठ)। रिक्ता तिथि व अमावस्या नए शुभ-कार्य हेतु त्याज्य, पर पितृ-कर्म हेतु अमावस्या उपयुक्त।', en: 'Auspicious tithis: 2nd, 3rd, 5th, 7th, 10th, 13th (Pradosh/Trayodashi and Monday are best for Shiva-remedies). Rikta tithis and Amavasya are avoided for new auspicious work, but Amavasya suits pitri-rites.' },
  regional: [
    { region: { hi: 'उज्जैन व त्र्यंबकेश्वर (काल सर्प)', en: 'Ujjain & Trimbakeshwar (Kaal Sarp)' }, text: { hi: 'काल सर्प दोष निवारण हेतु त्र्यंबकेश्वर (नासिक) व उज्जैन के मंगलनाथ/नागचंद्रेश्वर सर्वप्रसिद्ध हैं; नाग-प्रतिमा पूजन, राहु-केतु शांति व रुद्राभिषेक किए जाते हैं।', en: 'For Kaal Sarp Dosh, Trimbakeshwar (Nashik) and Ujjain\'s Mangalnath/Nagchandreshwar are most renowned; naga-idol worship, Rahu-Ketu shanti and rudrabhishek are performed.' } },
    { region: { hi: 'दक्षिण भारत (नवग्रह स्थल)', en: 'South India (Navagraha temples)' }, text: { hi: 'तमिलनाडु के नवग्रह-मंदिर (कुम्भकोणम् के पास) प्रत्येक ग्रह हेतु समर्पित; भक्त पीड़ित ग्रह के मंदिर में दीप, तिल-तेल व वस्त्र अर्पित कर परिक्रमा करते हैं।', en: 'Tamil Nadu\'s Navagraha temples (near Kumbakonam) are each dedicated to a planet; devotees offer lamps, sesame-oil and cloth at the afflicted planet\'s temple and circumambulate.' } },
    { region: { hi: 'गया व हरिद्वार (पितृ दोष)', en: 'Gaya & Haridwar (Pitra Dosha)' }, text: { hi: 'पितृ दोष निवारण हेतु गया (बिहार) में पिंडदान व श्राद्ध सर्वश्रेष्ठ माने जाते हैं; हरिद्वार, प्रयागराज व त्रिवेणी पर तर्पण व पितृपक्ष श्राद्ध की परंपरा।', en: 'For Pitra Dosha, pind-daan and shraddha at Gaya (Bihar) are held supreme; tarpan and Pitru-Paksha shraddha at Haridwar, Prayagraj and the Triveni are customary.' } },
    { region: { hi: 'शनि उपाय (शिंगणापुर व कोकिलावन)', en: 'Shani remedies (Shingnapur & Kokilavan)' }, text: { hi: 'शनि साढ़ेसाती/ढैया हेतु शनि शिंगणापुर (महाराष्ट्र) व कोकिलावन धाम प्रसिद्ध; शनिवार को तिल-तेल अभिषेक, नीले-काले वस्त्र व उड़द-दान की परंपरा।', en: 'For Shani Sade-Sati/Dhaiya, Shani Shingnapur (Maharashtra) and Kokilavan Dham are famed; Saturday sesame-oil abhishek, blue-black cloth and urad-daan are customary.' } },
    { region: { hi: 'सर्वत्र (नज़र-दोष)', en: 'Everywhere (Nazar-dosh)' }, text: { hi: 'बुरी नज़र उतारने हेतु राई-नमक या मिर्च वारना, नींबू-मिर्च द्वार पर बाँधना, काला टीका व काला धागा — ये लोक-परंपराएँ पूरे भारत में प्रचलित हैं।', en: 'To ward off the evil eye — circling mustard-salt or chillies, hanging a nimbu-mirchi at the door, a black tika and black thread — these folk customs are common across India.' } },
  ],
  preparation: [
    { hi: 'सर्वप्रथम योग्य ज्योतिषी से कुंडली-विश्लेषण कराएँ — कौन-सा ग्रह/दोष पीड़ित है व कौन-सा उपाय उपयुक्त है, यह जाने बिना उपाय न करें।', en: 'First have a qualified astrologer analyse the chart — do no remedy without knowing which planet/dosha is afflicted and which upaay suits.' },
    { hi: 'उपाय हेतु स्नान कर स्वच्छ वस्त्र (उपाय-अनुसार रंग — शनि हेतु नीला/काला, गुरु हेतु पीला) पहनें व संकल्प लें।', en: 'For the remedy, bathe and wear clean clothes (colour per the remedy — blue/black for Shani, yellow for Guru) and take the sankalp.' },
    { hi: 'नवग्रह शांति हेतु नवग्रह की धातु/समिधा, नवधान्य, संबंधित रंग के पुष्प-वस्त्र व दान-सामग्री पहले से जुटाएँ।', en: 'For Navagraha shanti, gather in advance the nine metals/samidha, navdhanya, flowers-cloth of the relevant colour and the daana-materials.' },
    { hi: 'महामृत्युंजय जप/हवन हेतु शिवलिंग, रुद्राक्ष-माला, बेलपत्र, गंगाजल, दूध व सफेद पुष्प रखें; जप-संकल्प की संख्या (जैसे सवा लाख) निश्चित करें।', en: 'For Mahamrityunjaya jaap/havan, keep a Shivling, rudraksha mala, bel-patra, Ganga-jal, milk and white flowers; fix the japa-count (e.g., 1.25 lakh).' },
    { hi: 'उपाय के साथ धैर्य, सत्कर्म, दान व संयम का संकल्प लें — शास्त्र कहते हैं उपाय तभी फलते हैं जब आचरण भी शुद्ध हो।', en: 'Alongside the remedy, resolve on patience, good deeds, charity and restraint — the shastras say remedies bear fruit only when conduct too is pure.' },
  ],
  samagri: [
    { name: { hi: 'नवग्रह मूर्ति/यंत्र व नवग्रह समिधा (9 लकड़ी)', en: 'Navagraha idol/yantra & navagraha samidha (nine woods)' }, reason: { hi: 'नवग्रह शांति पूजन व हवन का केंद्र; प्रत्येक ग्रह की समिधा उसी ग्रह की शांति हेतु।', en: 'The centre of navagraha shanti and havan; each planet\'s samidha for that planet\'s peace.' } },
    { name: { hi: 'नवधान्य (9 अन्न)', en: 'Navdhanya (nine grains)' }, reason: { hi: 'नवग्रह के प्रतीक; स्थापना, दान व हवन-आहुति हेतु।', en: 'Symbols of the nine planets; for sthapana, daana and havan-oblations.' } },
    { name: { hi: 'शिवलिंग / पारद-शिवलिंग व रुद्राक्ष-माला', en: 'Shivling / parad-shivling & rudraksha mala' }, reason: { hi: 'महामृत्युंजय जप, रुद्राभिषेक व शिव-उपासना हेतु।', en: 'For the Mahamrityunjaya jaap, rudrabhishek and Shiva worship.' } },
    { name: { hi: 'बेलपत्र, धतूरा, आक व सफेद पुष्प', en: 'Bel-patra, dhatura, aak & white flowers' }, reason: { hi: 'शिव-पूजन व अभिषेक में परम प्रिय अर्पण।', en: 'Offerings most dear to Shiva in worship and abhishek.' } },
    { name: { hi: 'गंगाजल, दूध, दही, घी, शहद व शक्कर (पंचामृत)', en: 'Ganga-jal, milk, curd, ghee, honey & sugar (panchamrit)' }, reason: { hi: 'रुद्राभिषेक व देव-अभिषेक हेतु शुद्धिकारक द्रव्य।', en: 'Purifying substances for the rudrabhishek and divine abhishek.' } },
    { name: { hi: 'काला तिल, तिल-तेल व सरसों-तेल', en: 'Black sesame, sesame-oil & mustard-oil' }, reason: { hi: 'शनि व राहु-केतु शांति में आहुति व दान; तिल-तेल अभिषेक शनि हेतु।', en: 'For Shani and Rahu-Ketu shanti — oblation and daana; sesame-oil abhishek for Shani.' } },
    { name: { hi: 'नौ रंग के वस्त्र/पुष्प', en: 'Cloth/flowers of nine colours' }, reason: { hi: 'प्रत्येक ग्रह के रंग-अनुसार अर्पण (सूर्य-लाल, गुरु-पीला, शनि-नीला/काला आदि)।', en: 'Offerings per each planet\'s colour (Sun-red, Guru-yellow, Shani-blue/black, etc.).' } },
    { name: { hi: 'नवग्रह दान-सामग्री (गुड़-गेहूँ, मूँग, मसूर, चना, तिल आदि)', en: 'Navagraha daana-items (jaggery-wheat, moong, masoor, chana, sesame, etc.)' }, reason: { hi: 'प्रत्येक ग्रह का निर्दिष्ट दान — ग्रह-शांति का मुख्य उपाय।', en: 'Each planet\'s prescribed donation — a chief means of graha-shanti.' } },
    { name: { hi: 'हवन कुंड, आम की समिधा, जौ व घी', en: 'Havan kund, mango samidha, barley & ghee' }, reason: { hi: 'शांति-हवन/मृत्युंजय हवन की आहुति हेतु।', en: 'For oblations in the shanti-havan / mrityunjaya havan.' } },
    { name: { hi: 'नाग-प्रतिमा (चाँदी/तांबा) — काल सर्प हेतु', en: 'Naga-idol (silver/copper) — for Kaal Sarp' }, reason: { hi: 'काल सर्प दोष निवारण में राहु-केतु/नाग-देवता पूजन हेतु।', en: 'For worshipping Rahu-Ketu/the serpent deity in Kaal Sarp Dosh nivaran.' } },
    { name: { hi: 'रोली, कुमकुम, अक्षत, मौली व कलश', en: 'Roli, kumkum, akshat, moli & kalash' }, reason: { hi: 'संकल्प, तिलक, रक्षासूत्र व देव-आवाहन की आधार-सामग्री।', en: 'Base materials for sankalp, tilak, the protective thread and invoking the deities.' } },
    { name: { hi: 'दीपक, धूप, कपूर व नैवेद्य', en: 'Lamp, incense, camphor & naivedya' }, reason: { hi: 'पूजन, आरती व भोग-अर्पण हेतु।', en: 'For the worship, aarti and bhog-offering.' } },
    { name: { hi: 'कुश, जौ, काला तिल व जल — पितृ-तर्पण हेतु', en: 'Kusha, barley, black sesame & water — for pitri-tarpan' }, reason: { hi: 'पितृ दोष निवारण में तर्पण व श्राद्ध की अनिवार्य सामग्री।', en: 'Essential for tarpan and shraddha in Pitra-dosha nivaran.' } },
    { name: { hi: 'दान हेतु अन्न, वस्त्र, धातु व दक्षिणा', en: 'Grain, cloth, metal & dakshina for daana' }, reason: { hi: 'ब्राह्मण/निर्धन को दान से शांति-कर्म का पुण्य पूर्ण होता है।', en: 'Daana to a brahmin/the needy completes the merit of the shanti-rite.' } },
  ],
  steps: [
    { title: { hi: 'ज्योतिषीय परामर्श व दोष-निर्धारण', en: 'Astrological consult & identifying the dosha' }, what: { hi: 'योग्य ज्योतिषी से कुंडली दिखाकर पीड़ित ग्रह/दोष (मंगल, शनि, राहु-केतु, पितृ आदि) व उपयुक्त उपाय निर्धारित कराएँ।', en: 'Show the chart to a qualified astrologer to identify the afflicted planet/dosha (Mangal, Shani, Rahu-Ketu, Pitra, etc.) and the fitting remedy.' }, why: { hi: 'बिना सही निदान के उपाय निरर्थक या अनुचित हो सकता है — निदान पहला व अनिवार्य चरण है।', en: 'Without a correct diagnosis a remedy may be futile or misplaced — diagnosis is the first, essential step.' } },
    { title: { hi: 'शुद्धि, संकल्प व गणेश-पूजन', en: 'Purification, Sankalp & Ganesha Puja' }, what: { hi: 'स्नान कर, स्वच्छ वस्त्र पहन, गंगाजल छिड़कें; हाथ में जल-अक्षत लेकर नाम-गोत्र व दोष-शांति का संकल्प लें व श्री गणेश का पूजन करें।', en: 'Bathe, wear clean clothes, sprinkle Ganga-jal; take water-akshat in hand with a sankalp naming yourself, gotra and the intended shanti, and worship Ganesha.' }, why: { hi: 'शुद्ध संकल्प व विघ्नहर्ता का स्मरण अनुष्ठान को निर्विघ्न व दिशा देता है।', en: 'A pure sankalp and remembrance of the obstacle-remover give the rite direction and smoothness.' }, deity: { hi: 'श्री गणेश', en: 'Lord Ganesha' } },
    { title: { hi: 'कलश स्थापना व नवग्रह आवाहन', en: 'Kalash Sthapana & Navagraha invocation' }, what: { hi: 'कलश स्थापित कर नवग्रह-मंडल बनाएँ; नवधान्य पर नवग्रह की स्थापना कर प्रत्येक ग्रह का आवाहन करें।', en: 'Establish the kalash and draw the navagraha-mandala; install the nine planets on the navdhanya and invoke each.' }, why: { hi: 'सभी ग्रहों को एक स्थान पर आमंत्रित कर सामूहिक शांति की जाती है।', en: 'All planets are invited to one place for a collective shanti.' }, deity: { hi: 'नवग्रह', en: 'The Navagraha' } },
    { title: { hi: 'नवग्रह पूजन व बीज-मंत्र जप', en: 'Navagraha Puja & beej-mantra japa' }, what: { hi: 'प्रत्येक ग्रह को उसके रंग के पुष्प-वस्त्र अर्पित कर उसके बीज-मंत्र का जप करें; पीड़ित ग्रह पर विशेष ध्यान दें।', en: 'Offer each planet flowers-cloth of its colour and chant its beej-mantra; give special attention to the afflicted planet.' }, why: { hi: 'ग्रह-विशेष मंत्र-जप उस ग्रह को बल व अनुकूलता प्रदान करता है।', en: 'Chanting a planet\'s mantra strengthens and favourably disposes it.' }, deity: { hi: 'नवग्रह', en: 'The Navagraha' } },
    { title: { hi: 'महामृत्युंजय जप', en: 'Mahamrityunjaya Jaap' }, what: { hi: 'शिवलिंग के समक्ष रुद्राक्ष-माला से महामृत्युंजय मंत्र का संकल्पित संख्या (108 / 1,25,000 सवा लाख) में जप करें।', en: 'Before the Shivling, chant the Mahamrityunjaya mantra with a rudraksha mala for the resolved count (108 / 1,25,000 — 1.25 lakh).' }, why: { hi: 'यह मंत्र भय, रोग व अकाल-मृत्यु के दोष की शांति हेतु सर्वश्रेष्ठ माना गया है।', en: 'This mantra is held supreme for pacifying fear, illness and the dosha of untimely death.' }, deity: { hi: 'भगवान शिव (मृत्युंजय)', en: 'Lord Shiva (Mrityunjaya)' } },
    { title: { hi: 'रुद्राभिषेक', en: 'Rudrabhishek' }, what: { hi: 'शिवलिंग पर जल, दूध, पंचामृत, गंगाजल व बेलपत्र से रुद्रमंत्रों सहित अभिषेक करें (विशेषतः सोमवार/श्रावण में)।', en: 'Bathe the Shivling with water, milk, panchamrit, Ganga-jal and bel-patra amid the Rudra mantras (especially on Mondays/in Shravan).' }, why: { hi: 'रुद्राभिषेक ग्रह-पीड़ा, रोग व नकारात्मकता की व्यापक शांति का सशक्त उपाय है।', en: 'Rudrabhishek is a powerful remedy for the broad pacification of planetary affliction, illness and negativity.' }, deity: { hi: 'भगवान शिव', en: 'Lord Shiva' } },
    { title: { hi: 'दोष-विशेष उपाय', en: 'Dosha-specific remedy' }, what: { hi: 'काल सर्प हेतु राहु-केतु/नाग पूजन, मंगल दोष हेतु मंगल/हनुमान उपासना, पितृ दोष हेतु तर्पण-श्राद्ध व पिंडदान, शनि हेतु तिल-तेल अभिषेक — निदान अनुसार करें।', en: 'For Kaal Sarp — Rahu-Ketu/naga puja; for Mangal Dosha — Mangal/Hanuman worship; for Pitra Dosha — tarpan-shraddha and pind-daan; for Shani — sesame-oil abhishek — as per diagnosis.' }, why: { hi: 'प्रत्येक दोष का अपना निर्दिष्ट, परंपरागत उपाय होता है।', en: 'Each dosha has its own prescribed, traditional remedy.' } },
    { title: { hi: 'शांति-हवन व पूर्णाहुति', en: 'Shanti-Havan & Purnahuti' }, what: { hi: 'हवन कुंड में अग्नि स्थापित कर नवग्रह व मृत्युंजय मंत्रों से आहुतियाँ दें; अंत में पूर्णाहुति अर्पित करें।', en: 'Kindle the fire and offer oblations with the navagraha and mrityunjaya mantras; conclude with the purnahuti.' }, why: { hi: 'अग्नि आहुति को देवताओं तक पहुँचाकर शांति-कर्म को पूर्ण व सशक्त करती है।', en: 'Agni carries the offerings to the deities, completing and empowering the shanti-rite.' }, deity: { hi: 'अग्निदेव व नवग्रह', en: 'Agni & the Navagraha' } },
    { title: { hi: 'ग्रह-दान व ब्राह्मण-भोज', en: 'Graha-Daana & Brahmin-bhoj' }, what: { hi: 'पीड़ित ग्रह की निर्दिष्ट वस्तु (शनि-तिल/तेल/उड़द, गुरु-हल्दी/चना दाल, राहु-नारियल/नीला वस्त्र आदि) का ब्राह्मण/निर्धन को दान करें व भोजन कराएँ।', en: 'Donate the afflicted planet\'s prescribed item (Shani – sesame/oil/urad, Guru – turmeric/chana dal, Rahu – coconut/blue cloth, etc.) to a brahmin/the needy and offer food.' }, why: { hi: 'दान ग्रह-शांति का शास्त्र-सम्मत व सर्वाधिक प्रभावी उपाय माना गया है।', en: 'Daana is regarded as a shastra-sanctioned and most effective means of graha-shanti.' } },
    { title: { hi: 'आरती, प्रार्थना व नियमित उपाय', en: 'Aarti, prayer & ongoing remedy' }, what: { hi: 'शिव व नवग्रह की आरती कर क्षमा-प्रार्थना करें; निर्दिष्ट वार-व्रत, नित्य मंत्र-जप व दान को नियमपूर्वक निरंतर रखें।', en: 'Perform the Shiva and navagraha aarti with a kshama-prarthana; keep up the prescribed weekday-fast, daily mantra-japa and charity consistently.' }, why: { hi: 'ग्रह-शांति एक बार का नहीं, निरंतर व धैर्यपूर्ण साधना का विषय है।', en: 'Graha-shanti is not a one-time act but a matter of steady, patient practice.' } },
  ],
  mantras: [
    { title: { hi: 'महामृत्युंजय मंत्र', en: 'Mahamrityunjaya Mantra' }, sanskrit: 'ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।\nउर्वारुकमिव बन्धनान्मृत्योर्मुक्षीय मामृतात्॥', roman: 'Om Tryambakam yajamahe sugandhim pushti-vardhanam.\nUrvarukam iva bandhanan mrityor mukshiya mamritat.', meaning: { hi: 'हम त्रिनेत्र शिव का पूजन करते हैं, जो सुगंधित व पोषण-वर्धक हैं; जैसे पका खरबूजा बेल से सहज ही अलग हो जाता है, वैसे ही हमें मृत्यु के बंधन से मुक्त कर अमरता प्रदान करें।', en: 'We worship the three-eyed Shiva, fragrant and nourishing; as a ripe cucumber is freed from its stem, may he free us from the bondage of death for immortality.' }, when: { hi: 'रोग, भय व अकाल-मृत्यु दोष की शांति हेतु', en: 'For pacifying illness, fear and the dosha of untimely death' }, count: '108 / सवा लाख (1,25,000)' },
    { title: { hi: 'नवग्रह स्तोत्र (सामूहिक ध्यान)', en: 'Navagraha Stotra (collective dhyana)' }, sanskrit: 'ब्रह्मा मुरारिस्त्रिपुरान्तकारी भानुः शशी भूमिसुतो बुधश्च।\nगुरुश्च शुक्रः शनिराहुकेतवः कुर्वन्तु सर्वे मम सुप्रभातम्॥', roman: 'Brahma Murarist-tripurantakari Bhanuh Shashi Bhumisuto Budhashcha.\nGurushcha Shukrah Shani-Rahu-Ketavah kurvantu sarve mama suprabhatam.', meaning: { hi: 'ब्रह्मा, विष्णु, शिव तथा सूर्य, चंद्र, मंगल, बुध, गुरु, शुक्र, शनि, राहु व केतु — ये सभी मेरा प्रभात (जीवन) मंगलमय करें।', en: 'Brahma, Vishnu, Shiva and Surya, Chandra, Mangal, Budh, Guru, Shukra, Shani, Rahu and Ketu — may all of them make my morning (life) auspicious.' }, when: { hi: 'नवग्रह पूजन व प्रात: स्मरण में', en: 'During navagraha puja & morning remembrance' }, count: '3 / 11' },
    { title: { hi: 'शनि बीज व वैदिक मंत्र', en: 'Shani beej & Vedic mantra' }, sanskrit: 'ॐ प्रां प्रीं प्रौं सः शनैश्चराय नमः॥\nॐ शन्नो देवीरभिष्टय आपो भवन्तु पीतये।\nशं योरभि स्रवन्तु नः॥', roman: 'Om Praam Preem Praum Sah Shanaishcharaya Namah.\nOm sham no devir abhishtaya apo bhavantu pitaye.\nSham yor abhi sravantu nah.', meaning: { hi: 'शनैश्चर (शनि) देव को नमन; हे देव, आपकी कृपा से जल-सम कल्याण व शांति हमें प्राप्त हो। (साढ़ेसाती/ढैया की शांति हेतु)', en: 'Salutations to Shanaishchara (Saturn); by your grace, may water-like welfare and peace reach us. (For Sade-Sati/Dhaiya shanti)' }, when: { hi: 'शनिवार — शनि साढ़ेसाती/ढैया उपाय में', en: 'On Saturdays — in Shani Sade-Sati/Dhaiya remedies' }, count: '23,000 / 108 प्रतिदिन' },
    { title: { hi: 'राहु-केतु बीज मंत्र (काल सर्प)', en: 'Rahu-Ketu beej mantra (Kaal Sarp)' }, sanskrit: 'ॐ भ्रां भ्रीं भ्रौं सः राहवे नमः॥\nॐ स्रां स्रीं स्रौं सः केतवे नमः॥', roman: 'Om Bhraam Bhreem Bhraum Sah Rahave Namah.\nOm Sraam Sreem Sraum Sah Ketave Namah.', meaning: { hi: 'राहु देव व केतु देव को नमन — काल सर्प दोष व राहु-केतु पीड़ा की शांति हेतु आवाहन।', en: 'Salutations to Rahu and Ketu — invoked for pacifying Kaal Sarp Dosh and Rahu-Ketu affliction.' }, when: { hi: 'काल सर्प दोष निवारण व राहु-केतु शांति में', en: 'In Kaal Sarp Dosh nivaran & Rahu-Ketu shanti' }, count: '18,000 (राहु) / 17,000 (केतु)' },
    { title: { hi: 'मंगल दोष उपाय — हनुमान/मंगल मंत्र', en: 'Mangal Dosha remedy — Hanuman/Mangal mantra' }, sanskrit: 'ॐ क्रां क्रीं क्रौं सः भौमाय नमः॥\nॐ हं हनुमते रुद्रात्मकाय हुं फट्॥', roman: 'Om Kraam Kreem Kraum Sah Bhaumaya Namah.\nOm Ham Hanumate Rudratmakaya Hum Phat.', meaning: { hi: 'मंगल (भौम) देव व रुद्रावतार हनुमान को नमन — मंगल दोष (मांगलिक) की शांति व साहस-रक्षा हेतु।', en: 'Salutations to Mangal (Bhauma) and Hanuman, the Rudra-incarnate — for pacifying Mangal Dosha (Manglik) and for courage and protection.' }, when: { hi: 'मंगलवार — मंगल दोष उपाय व हनुमान उपासना में', en: 'On Tuesdays — in Mangal Dosha remedies & Hanuman worship' }, count: '108 / 10,000' },
    { title: { hi: 'महालक्ष्मी / गायत्री (सर्व-शांति)', en: 'Mahalakshmi / Gayatri (general shanti)' }, sanskrit: 'ॐ भूर्भुवः स्वः तत्सवितुर्वरेण्यं\nभर्गो देवस्य धीमहि धियो यो नः प्रचोदयात्॥', roman: 'Om bhur bhuvah svah tat savitur varenyam\nbhargo devasya dhimahi dhiyo yo nah prachodayat.', meaning: { hi: 'उस सविता (सूर्य) देव के श्रेष्ठ तेज का हम ध्यान करते हैं, जो हमारी बुद्धि को सन्मार्ग की ओर प्रेरित करें — यह सर्व-दोष शांति का आधार मंत्र है।', en: 'We meditate on the supreme radiance of Savitr (the Sun); may it inspire our intellect toward righteousness — a base mantra for the peace of all doshas.' }, when: { hi: 'नित्य — सर्व-ग्रह शांति व मानसिक शांति हेतु', en: 'Daily — for all-planet shanti and peace of mind' }, count: '108' },
  ],
  aartis: [
    { title: { hi: 'ॐ जय शिव ओंकारा', en: 'Om Jai Shiv Omkara' }, lines: 'ॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा।\nब्रह्मा विष्णु सदाशिव, अर्द्धांगी धारा॥\n(महामृत्युंजय/रुद्राभिषेक के अंत में शिव-आरती गाएँ।)' },
    { title: { hi: 'श्री नवग्रह आरती', en: 'Shri Navagraha Aarti' }, lines: 'आरती नवग्रह देवन की, कृपा-दृष्टि सब पर करनी।\n(सूर्य-चंद्र-मंगल-बुध-गुरु-शुक्र-शनि-राहु-केतु की संयुक्त आरती।)' },
  ],
  dos: [
    { hi: 'कोई भी उपाय करने से पूर्व योग्य ज्योतिषी/पुरोहित से कुंडली-परामर्श अवश्य लें।', en: 'Always take a chart-consult from a qualified astrologer/purohit before any remedy.' },
    { hi: 'उपाय को श्रद्धा, धैर्य व नियमितता से करें — मंत्र-जप, वार-व्रत व दान निरंतर रखें।', en: 'Do the remedy with faith, patience and regularity — keep up the japa, weekday-fast and charity consistently.' },
    { hi: 'दान व सेवा (अन्न, वस्त्र, तिल-तेल, गौ-सेवा) को प्राथमिकता दें — यह शांति का सरल व प्रभावी उपाय है।', en: 'Prioritise charity and service (grain, cloth, sesame-oil, cow-service) — a simple and effective means of shanti.' },
    { hi: 'सत्कर्म, सत्य-व्यवहार व संयम को उपाय का अंग बनाएँ; उपाय व सद्आचरण साथ-साथ चलें।', en: 'Make good deeds, honesty and restraint part of the remedy; upaay and right conduct go together.' },
    { hi: 'रत्न/यंत्र धारण करने से पूर्व विशेषज्ञ से ग्रह-बल व अनुकूलता की पुष्टि कराएँ।', en: 'Before wearing a gem/yantra, confirm the planet\'s strength and suitability with an expert.' },
  ],
  donts: [
    { hi: 'बिना कुंडली-निदान के, सुनी-सुनाई बातों पर उपाय, रत्न या अनुष्ठान न करें।', en: 'Do not do remedies, gems or rituals on hearsay, without a chart-diagnosis.' },
    { hi: 'भय या दबाव में महँगे "गारंटीड समाधान" के झाँसे में न आएँ; ठगी व अंधविश्वास से बचें।', en: 'Do not fall for costly "guaranteed solution" traps out of fear or pressure; avoid fraud and blind superstition.' },
    { hi: 'दोष के भय से चिकित्सा, कानूनी या वित्तीय आवश्यक निर्णय न टालें — उपाय इनका विकल्प नहीं।', en: 'Do not postpone necessary medical, legal or financial decisions out of fear of a dosha — remedies are no substitute for these.' },
    { hi: 'किसी को "दोषी/मांगलिक" कहकर अपमानित या विवाह-संबंध में भेदभाव न करें।', en: 'Do not insult anyone as "doshi/manglik" or discriminate in marriage matters.' },
    { hi: 'उपाय के नाम पर हिंसा, तंत्र-अभिचार या किसी अनैतिक कर्म का सहारा न लें।', en: 'Do not resort to violence, black-magic or any unethical act in the name of a remedy.' },
  ],
  mistakes: [
    { hi: 'स्वयं निदान कर बिना विशेषज्ञ के रत्न/मंत्र चुन लेना — गलत उपाय हानिकारक हो सकता है।', en: 'Self-diagnosing and picking a gem/mantra without an expert — a wrong remedy can harm.' },
    { hi: 'एक बार पूजा कराकर उपाय को पूर्ण मान लेना — ग्रह-शांति निरंतर साधना माँगती है।', en: 'Treating one puja as the whole remedy — graha-shanti demands ongoing practice.' },
    { hi: 'उपाय पर निर्भर होकर पुरुषार्थ, चिकित्सा व कर्तव्य छोड़ देना।', en: 'Relying on remedies while abandoning effort, medical care and duty.' },
    { hi: 'ग्रह-दोष के भय को मन पर हावी होने देना — शास्त्र भी कहते हैं कि श्रद्धा व सत्कर्म भय से बड़े हैं।', en: 'Letting fear of a dosha overwhelm the mind — the shastras too say faith and good deeds outweigh fear.' },
  ],
  faqs: [
    { q: { hi: 'क्या ग्रह-दोष के उपाय सचमुच काम करते हैं?', en: 'Do graha-dosha remedies really work?' }, a: { hi: 'ज्योतिष व परंपरा में इन्हें कर्म-फल संतुलित करने वाला सहायक उपाय माना जाता है; ये श्रद्धा, धैर्य व सत्कर्म के साथ मानसिक बल व सकारात्मकता देते हैं। यह वैज्ञानिक/चिकित्सकीय गारंटी नहीं।', en: 'In Jyotish and tradition these are held to be aids that balance karmic results; with faith, patience and good deeds they give mental strength and positivity. They are not a scientific/medical guarantee.' } },
    { q: { hi: 'सबसे सरल व सुरक्षित उपाय कौन-से हैं?', en: 'What are the simplest, safest remedies?' }, a: { hi: 'नित्य मंत्र-जप (गायत्री, महामृत्युंजय), संबंधित वार का व्रत, दान-सेवा व सत्कर्म — ये बिना किसी हानि के सर्वसुलभ उपाय हैं।', en: 'Daily japa (Gayatri, Mahamrityunjaya), a weekday-fast, charity-service and good conduct — the most accessible remedies, with no downside.' } },
    { q: { hi: 'मांगलिक (मंगल दोष) का क्या अर्थ है?', en: 'What does Manglik (Mangal Dosha) mean?' }, a: { hi: 'कुंडली के 1/4/7/8/12वें भाव में मंगल की स्थिति को मांगलिक कहा जाता है; इसके पारंपरिक उपाय (हनुमान/मंगल उपासना, कुंभ-विवाह आदि) हैं। दो मांगलिक का मिलान दोष-शमन माना जाता है — पर यह किसी को हीन ठहराने का आधार नहीं।', en: 'Mars in the 1st/4th/7th/8th/12th house is called Manglik; it has traditional remedies (Hanuman/Mangal worship, kumbh-vivah, etc.). Matching two Mangliks is held to cancel the dosha — but it is no basis to demean anyone.' } },
    { q: { hi: 'काल सर्प दोष कितना गंभीर है?', en: 'How serious is Kaal Sarp Dosh?' }, a: { hi: 'जब सभी ग्रह राहु-केतु के बीच आ जाएँ तो काल सर्प योग बनता है; कई विद्वान इसे अतिरंजित मानते हैं। त्र्यंबकेश्वर/उज्जैन में पूजा, महामृत्युंजय जप व नाग-पूजन इसके प्रचलित उपाय हैं। घबराएँ नहीं, विशेषज्ञ से मार्गदर्शन लें।', en: 'Kaal Sarp Yoga forms when all planets fall between Rahu and Ketu; many scholars consider it exaggerated. Puja at Trimbakeshwar/Ujjain, Mahamrityunjaya jaap and naga-puja are its common remedies. Do not panic; seek expert guidance.' } },
    { q: { hi: 'पितृ दोष का उपाय क्या है?', en: 'What is the remedy for Pitra Dosha?' }, a: { hi: 'अमावस्या व पितृपक्ष में तर्पण, श्राद्ध व (गया में) पिंडदान; ब्राह्मण/निर्धन को अन्न-वस्त्र दान, गौ-कौआ-कुत्ते को भोजन तथा पूर्वजों के प्रति श्रद्धा — ये मुख्य उपाय हैं।', en: 'Tarpan, shraddha and (at Gaya) pind-daan on Amavasya and in Pitru Paksha; donating grain-cloth to a brahmin/the needy, feeding the cow-crow-dog, and reverence for the ancestors — the chief remedies.' } },
    { q: { hi: 'क्या ये उपाय चिकित्सा या कानूनी सलाह का विकल्प हैं?', en: 'Are these remedies a substitute for medical or legal advice?' }, a: { hi: 'बिल्कुल नहीं। ये पारंपरिक आस्था-आधारित उपाय हैं; रोग, कानूनी व वित्तीय समस्याओं में योग्य डॉक्टर, वकील व सलाहकार से ही परामर्श लें। उपाय इनका पूरक हो सकते हैं, विकल्प नहीं।', en: 'Absolutely not. These are traditional, faith-based remedies; for illness, legal and financial matters, consult only a qualified doctor, lawyer and advisor. Remedies may complement, never replace, these.' } },
  ],
  estTime: { hi: 'सरल जप ~15–30 मिनट/दिन · नवग्रह शांति/हवन ~2–4 घंटे · जप-अनुष्ठान कई दिन', en: 'Simple japa ~15–30 min/day · Navagraha shanti/havan ~2–4 hrs · japa-anushthan over several days' },
  difficulty: { hi: 'मध्यम–उच्च · ज्योतिषी/पुरोहित परामर्श आवश्यक', en: 'Moderate–Advanced · astrologer/purohit consult needed' },
  disclaimer: {
    hi: 'यहाँ दिए उपाय सामान्य पारंपरिक ज्योतिषीय आस्था पर आधारित हैं तथा केवल जानकारी हेतु हैं — ये किसी वैज्ञानिक, चिकित्सकीय, कानूनी या वित्तीय सलाह के विकल्प नहीं हैं। ग्रह-दोष व उसके उपाय कुंडली, क्षेत्र, परंपरा व कुलाचार अनुसार भिन्न होते हैं। कोई भी अनुष्ठान, रत्न या दान करने से पूर्व योग्य ज्योतिषी/पुरोहित का परामर्श सर्वोपरि है; किसी भी समस्या में संबंधित विशेषज्ञ (डॉक्टर, वकील, सलाहकार) से अवश्य मिलें। भय, अंधविश्वास व ठगी से बचें।',
    en: 'The remedies here rest on general traditional astrological belief and are for information only — they are not a substitute for scientific, medical, legal or financial advice. A graha-dosha and its remedy vary by chart, region, tradition and family lineage (kulachar). Before any ritual, gem or donation, a qualified astrologer\'s/purohit\'s guidance is supreme; for any real problem, do consult the relevant professional (doctor, lawyer, advisor). Avoid fear, superstition and fraud.',
  },
};

