/* ─────────────────────────────────────────────────────────────────────────
 * VRAT (व्रत) — a reusable fasting-vidhi guide: types (nirjala/phalahar/
 * saatvik), sankalp, snana, worship of the vrat-devata, vrat-katha shravan,
 * niyam (eat/avoid), paran (breaking the fast correctly & timing), udyapan.
 * Cross-referenced: drikpanchang (Ekadashi vidhi-vidhan & parana, Karwa Chauth
 * vidhi), 99pandit (Hindu vrat list), sanatanajourney (Ekadashi niyam).
 * Examples: Ekadashi, Karva Chauth, Somvar, Shani, Santoshi Mata, Navratri.
 * Kulachar + purohit is supreme; regional customs vary.
 * ──────────────────────────────────────────────────────────────────────── */
const VRAT: CuratedOccasion = {
  intro: {
    hi: 'व्रत (उपवास) सनातन साधना का प्राण है — यह केवल भूखा रहना नहीं, बल्कि "उप + वास" अर्थात् इष्ट देव के समीप वास करना है। संकल्पपूर्वक आहार, वाणी व इंद्रियों का संयम कर मन को देव-चिंतन में लगाना ही व्रत का मर्म है। इससे शरीर की शुद्धि, इच्छाशक्ति की वृद्धि व पाप-क्षय होता है और मनोकामना-सिद्धि मानी जाती है। यह मार्गदर्शिका किसी भी व्रत को करने की सामान्य वैदिक विधि बताती है — व्रत के प्रकार, संकल्प, प्रातः स्नान, व्रत-देवता का पूजन, व्रत-कथा श्रवण, नियम (क्या खाएँ-क्या त्यागें), पारण (व्रत का सही समय व विधि से समापन) तथा उद्यापन।',
    en: 'A vrat (fast) is the very life-breath of Sanatana sadhana — it is not merely going hungry but "upa + vasa", dwelling close to one\'s ishta-devata. Restraining food, speech and the senses with a sankalp and fixing the mind on the Divine is the essence of a vrat. It purifies the body, strengthens the will, dissolves sin and is believed to fulfil one\'s heart\'s desires. This guide gives the general Vedic method for observing any vrat — its types, the sankalp, the morning bath, worship of the vrat-devata, hearing the vrat-katha, the niyam (what to eat/avoid), the paran (correctly breaking the fast at the right time) and the udyapan.',
  },
  significance: [
    { hi: 'व्रत तीन प्रकार का होता है — (1) निर्जल: बिना जल-अन्न का कठोर उपवास (जैसे निर्जला एकादशी, करवा चौथ), (2) फलाहार: केवल फल, दूध व व्रत-अन्न (साबूदाना, कुट्टू, सिंघाड़ा), (3) सात्त्विक/एक-भुक्त: दिन में एक बार सात्त्विक अन्न।', en: 'A vrat is of three kinds — (1) Nirjala: a strict fast without water or food (e.g. Nirjala Ekadashi, Karva Chauth), (2) Phalahar: only fruit, milk and vrat-grains (sabudana, kuttu, singhara), (3) Saatvik/ek-bhukt: one sattvic meal in the day.' },
    { hi: 'व्रत से इंद्रिय-संयम, आत्म-अनुशासन व संकल्प-शक्ति बढ़ती है; भोजन-विराम से शरीर व पाचन को विश्राम मिलता है।', en: 'A vrat builds sense-control, self-discipline and will-power; the pause from food rests the body and digestion.' },
    { hi: 'शास्त्रानुसार व्रत से पाप-क्षय, पुण्य-वृद्धि व इष्ट देव की विशेष कृपा प्राप्त होती है।', en: 'By the shastras, a vrat dissolves sin, increases merit and secures the special grace of one\'s ishta-devata.' },
    { hi: 'प्रत्येक व्रत का अपना देव व फल है — एकादशी (विष्णु, मोक्ष), सोमवार (शिव), मंगल (हनुमान), शनि (शनिदेव), करवा चौथ (गौरी-गणेश, पति-दीर्घायु), संतोषी माता (सुख-संतोष)।', en: 'Each vrat has its own deity and fruit — Ekadashi (Vishnu, liberation), Monday (Shiva), Tuesday (Hanuman), Saturday (Shani), Karva Chauth (Gauri-Ganesha, husband\'s long life), Santoshi Mata (contentment).' },
    { hi: 'व्रत-कथा श्रवण व दान से मन शुद्ध होता है व व्रत का पूर्ण फल मिलता है।', en: 'Hearing the vrat-katha and giving daana purify the mind and yield the full fruit of the vrat.' },
  ],
  history: {
    hi: 'व्रत-परंपरा वेद, पुराण व स्मृति-ग्रंथों में गहराई से वर्णित है — विशेषकर पद्म पुराण, स्कंद पुराण व भविष्य पुराण में एकादशी, प्रदोष, नवरात्रि आदि व्रतों का माहात्म्य व कथाएँ मिलती हैं। "उपवास" का अर्थ ही है देव के समीप वास — यही व्रत का मूल आध्यात्मिक भाव है।',
    en: 'The vrat tradition is deeply described in the Vedas, Puranas and Smriti texts — especially the Padma, Skanda and Bhavishya Puranas, which record the glory and legends of Ekadashi, Pradosh, Navratri and other vrats. "Upavasa" itself means dwelling near the deity — the core spiritual sense of a vrat.',
  },
  muhurat: {
    hi: 'व्रत की तिथि पंचांग से निर्धारित होती है (जैसे एकादशी = शुक्ल/कृष्ण एकादशी, प्रदोष = त्रयोदशी, संकष्टी = कृष्ण चतुर्थी)। उदयातिथि का पालन प्रमुख है। सबसे महत्वपूर्ण है "पारण" का सही समय — व्रत तोड़ने का काल शास्त्र-सम्मत होना चाहिए (जैसे एकादशी का पारण द्वादशी को, हरि-वासर के बाद)।',
    en: 'The vrat\'s date is fixed by the panchang (e.g. Ekadashi = Shukla/Krishna Ekadashi, Pradosh = Trayodashi, Sankashti = Krishna Chaturthi). Following the udaya-tithi is key. Most important is the correct "paran" time — the fast must be broken in the scripturally sanctioned window (e.g. Ekadashi\'s paran on Dwadashi, after the Hari-Vasara).',
  },
  tithi: {
    hi: 'व्रत पंचांग की तिथि पर रखें व उदयातिथि का पालन करें। पारण-समय अवश्य देखें: एकादशी व्रत का पारण अगले दिन द्वादशी को सूर्योदय-बाद, हरि-वासर (द्वादशी का प्रथम चौथाई) समाप्त होने पर करें; करवा चौथ में चंद्र-दर्शन के बाद पारण होता है।', en: 'Keep the vrat on the panchang tithi and follow the udaya-tithi. Always check the paran time: break the Ekadashi vrat on the next day (Dwadashi) after sunrise, once the Hari-Vasara (the first quarter of Dwadashi) has passed; in Karva Chauth the paran is after sighting the moon.',
  },
  regional: [
    { region: { hi: 'एकादशी (विष्णु व्रत)', en: 'Ekadashi (Vishnu Vrat)' }, text: { hi: 'माह में दो बार; अन्न (विशेषकर चावल) का पूर्ण त्याग, फलाहार या निर्जल व्रत, विष्णु-पूजन व "ॐ नमो भगवते वासुदेवाय" जप, रात्रि-जागरण; पारण द्वादशी को हरि-वासर के बाद।', en: 'Twice a month; total avoidance of grains (especially rice), phalahar or nirjala fast, Vishnu-worship and japa of "Om Namo Bhagavate Vasudevaya", a night-vigil; paran on Dwadashi after the Hari-Vasara.' } },
    { region: { hi: 'करवा चौथ', en: 'Karva Chauth' }, text: { hi: 'सुहागिनें पति की दीर्घायु हेतु निर्जल व्रत रखती हैं; सरगी (प्रातः), दिनभर उपवास, संध्या को गौरी-गणेश व करवा-पूजन, कथा-श्रवण, छलनी से चंद्र व पति-दर्शन के बाद जल-भोजन से पारण।', en: 'Married women keep a nirjala fast for the husband\'s long life; sargi (pre-dawn), a day-long fast, evening worship of Gauri-Ganesha and the karva, hearing the katha, and paran with water-food after viewing the moon and husband through a sieve.' } },
    { region: { hi: 'सोमवार व्रत (शिव)', en: 'Monday Vrat (Shiva)' }, text: { hi: 'शिव-पार्वती हेतु; शिवलिंग पर जल-बेलपत्र अर्पण, "ॐ नमः शिवाय" जप, एक-भुक्त/फलाहार, सोलह सोमवार व्रत विशेष प्रचलित।', en: 'For Shiva-Parvati; offering water and bel-patra to the Shivalinga, japa of "Om Namah Shivaya", one meal/phalahar; the Solah Somvar vrat is especially popular.' } },
    { region: { hi: 'शनि व मंगल व्रत', en: 'Saturday & Tuesday Vrat' }, text: { hi: 'शनिवार शनिदेव/हनुमान हेतु (तेल-दीप, काला तिल-उड़द दान); मंगलवार हनुमान हेतु (सुंदरकांड, गुड़-चने का भोग) — साढ़ेसाती व संकट-निवारण हेतु।', en: 'Saturday for Shani/Hanuman (oil-lamp, donating black sesame-urad); Tuesday for Hanuman (Sundarkand, jaggery-gram bhog) — for Sade Sati and relief from troubles.' } },
    { region: { hi: 'संतोषी माता व नवरात्रि', en: 'Santoshi Mata & Navratri' }, text: { hi: 'संतोषी माता का शुक्रवार व्रत (16 शुक्रवार, गुड़-चना भोग, खट्टा वर्जित); नवरात्रि में नौ दिन का व्रत, फलाहार व माँ दुर्गा-पूजन, अष्टमी/नवमी पर कन्या-पूजन से पारण/उद्यापन।', en: 'Santoshi Mata\'s Friday vrat (16 Fridays, jaggery-gram bhog, sour foods forbidden); Navratri\'s nine-day vrat, phalahar and Durga-worship, with paran/udyapan through kanya-pujan on Ashtami/Navami.' } },
  ],
  preparation: [
    { hi: 'एक दिन पूर्व से सात्त्विक आहार लें व मन को व्रत हेतु तैयार करें; व्रत-वाले दिन ब्रह्ममुहूर्त में उठें।', en: 'Eat sattvic food from the day before and prepare the mind for the vrat; on the vrat day rise in the Brahma-muhurta.' },
    { hi: 'प्रातः स्नान कर स्वच्छ वस्त्र धारण करें; पूजा-स्थान की सफाई कर व्रत-देवता की मूर्ति/चित्र स्थापित करें।', en: 'Bathe in the morning and wear clean clothes; clean the puja area and install the vrat-devata\'s idol/photo.' },
    { hi: 'व्रत के प्रकार (निर्जल/फलाहार/एक-भुक्त) का निश्चय करें व आवश्यक व्रत-सामग्री (फल, व्रत-अन्न, दूध) जुटा लें।', en: 'Decide the type of vrat (nirjala/phalahar/ek-bhukt) and gather the needed vrat-samagri (fruit, vrat-grains, milk).' },
    { hi: 'व्रत-कथा पुस्तक, पूजन-सामग्री व पारण-समय (पंचांग) पहले से देख लें ताकि व्रत विधिपूर्वक पूर्ण हो।', en: 'Keep the vrat-katha book, puja items and the paran time (from the panchang) ready in advance so the vrat is completed correctly.' },
  ],
  samagri: [
    { name: { hi: 'व्रत-देवता की मूर्ति/चित्र', en: 'Vrat-devata idol/photo' }, reason: { hi: 'व्रत के आराध्य देव (विष्णु/शिव/हनुमान/गौरी आदि) का आवाहन व पूजन।', en: 'To invoke and worship the vrat\'s deity (Vishnu/Shiva/Hanuman/Gauri etc.).' } },
    { name: { hi: 'घी/तेल का दीपक', en: 'Ghee/oil lamp' }, reason: { hi: 'दीप प्रज्वलन व आरती हेतु; शनि-व्रत में तेल-दीप विशेष।', en: 'For lighting the lamp and aarti; an oil-lamp is special in the Shani vrat.' } },
    { name: { hi: 'रोली, अक्षत, कुमकुम, चंदन', en: 'Roli, akshat, kumkum, sandal' }, reason: { hi: 'तिलक, संकल्प व देव-अर्पण हेतु।', en: 'For tilak, sankalp and offerings.' } },
    { name: { hi: 'पुष्प, माला व देव-प्रिय पत्र', en: 'Flowers, garland & deity-leaves' }, reason: { hi: 'देव-अर्पण; शिव को बेलपत्र, विष्णु को तुलसी, देवी को लाल पुष्प।', en: 'For offering; bel-patra to Shiva, tulsi to Vishnu, red flowers to the Devi.' } },
    { name: { hi: 'धूप/अगरबत्ती व कपूर', en: 'Incense & camphor' }, reason: { hi: 'सुगंध व आरती हेतु।', en: 'For fragrance and aarti.' } },
    { name: { hi: 'पंचामृत व गंगाजल', en: 'Panchamrit & Ganga-jal' }, reason: { hi: 'देव-अभिषेक व शुद्धि हेतु।', en: 'For the deity\'s abhishek and purification.' } },
    { name: { hi: 'फल, दूध व व्रत-अन्न (साबूदाना, कुट्टू, सिंघाड़ा)', en: 'Fruit, milk & vrat-grains (sabudana, kuttu, singhara)' }, reason: { hi: 'फलाहार व्रत का भोजन तथा देव-नैवेद्य।', en: 'Food for the phalahar vrat and for the deity\'s naivedya.' } },
    { name: { hi: 'सेंधा नमक', en: 'Rock salt (sendha namak)' }, reason: { hi: 'व्रत में साधारण नमक वर्जित; केवल सेंधा नमक ग्राह्य।', en: 'Ordinary salt is forbidden in a vrat; only rock salt is permitted.' } },
    { name: { hi: 'भोग/नैवेद्य (देव-अनुसार)', en: 'Bhog/naivedya (per deity)' }, reason: { hi: 'गौरी-गणेश को मिठाई, हनुमान को गुड़-चना, संतोषी माता को गुड़-चना (खट्टा नहीं)।', en: 'Sweets for Gauri-Ganesha, jaggery-gram for Hanuman, jaggery-gram for Santoshi Mata (nothing sour).' } },
    { name: { hi: 'करवा/कलश व जल-पात्र', en: 'Karva/kalash & water vessel' }, reason: { hi: 'करवा चौथ में करवा-पूजन व अर्घ्य; अन्य व्रतों में कलश-स्थापना।', en: 'For karva-worship and arghya in Karva Chauth; kalash-sthapana in other vrats.' } },
    { name: { hi: 'छलनी (करवा चौथ)', en: 'Sieve (Karva Chauth)' }, reason: { hi: 'चंद्र व पति-दर्शन कर पारण की रस्म हेतु।', en: 'For viewing the moon and husband before the paran ritual.' } },
    { name: { hi: 'व्रत-कथा पुस्तक व आसन', en: 'Vrat-katha book & seat' }, reason: { hi: 'कथा-श्रवण व पूजन में बैठने हेतु।', en: 'For hearing the katha and for seating during worship.' } },
    { name: { hi: 'दक्षिणा व दान-सामग्री', en: 'Dakshina & daana items' }, reason: { hi: 'व्रत-समापन व उद्यापन पर ब्राह्मण/ज़रूरतमंद को दान हेतु।', en: 'For giving to a brahmin/the needy at the conclusion and udyapan of the vrat.' } },
  ],
  steps: [
    { title: { hi: 'प्रातः स्नान व शुद्धि', en: 'Morning Bath & Purification' }, what: { hi: 'ब्रह्ममुहूर्त में उठकर स्नान करें, स्वच्छ वस्त्र पहनें व पूजा-स्थान पर गंगाजल छिड़कें।', en: 'Rise in the Brahma-muhurta, bathe, wear clean clothes and sprinkle Ganga-jal at the puja place.' }, why: { hi: 'व्रत का आरंभ तन-मन की शुद्धि से ही फलदायी होता है।', en: 'A vrat begun with bodily-mental purity alone bears fruit.' } },
    { title: { hi: 'व्रत संकल्प', en: 'Vrat Sankalp' }, what: { hi: 'हाथ में जल, अक्षत व पुष्प लेकर व्रत का संकल्प लें — कौन-सा व्रत, किस देव हेतु, किस कामना से व किस प्रकार (निर्जल/फलाहार) का, यह स्पष्ट कहें।', en: 'Take water, akshat and a flower in hand and make the vrat sankalp — clearly state which vrat, for which deity, with what wish and of what type (nirjala/phalahar).' }, why: { hi: 'संकल्प के बिना व्रत अधूरा है; यही व्रत को दिशा व देव-साक्षी देता है।', en: 'Without the sankalp a vrat is incomplete; it gives the vrat its purpose and divine witness.' } },
    { title: { hi: 'गणेश व व्रत-देवता पूजन', en: 'Ganesha & Vrat-devata Puja' }, what: { hi: 'सर्वप्रथम गणेश-पूजन कर, फिर व्रत के आराध्य देव का आवाहन व षोडशोपचार (या पंचोपचार) पूजन करें।', en: 'First worship Ganesha, then invoke the vrat\'s deity and perform the shodashopachara (or panchopachara) worship.' }, why: { hi: 'गणेश प्रथम-पूज्य हैं; व्रत-देव का पूजन ही व्रत का केंद्र है।', en: 'Ganesha is worshipped first; worship of the vrat-deity is the heart of the vrat.' }, deity: { hi: 'गणेश व व्रत-देवता', en: 'Ganesha & the vrat-devata' } },
    { title: { hi: 'मंत्र-जप व स्तोत्र-पाठ', en: 'Mantra-japa & Stotra' }, what: { hi: 'व्रत-देव के मूल मंत्र का जप व स्तोत्र-पाठ करें (विष्णु: ॐ नमो भगवते वासुदेवाय; शिव: ॐ नमः शिवाय; हनुमान: सुंदरकांड/हनुमान चालीसा)।', en: 'Chant the vrat-deity\'s root mantra and recite the stotra (Vishnu: Om Namo Bhagavate Vasudevaya; Shiva: Om Namah Shivaya; Hanuman: Sundarkand/Hanuman Chalisa).' }, why: { hi: 'मंत्र-जप से मन एकाग्र होता है व व्रत का फल बढ़ता है।', en: 'Japa steadies the mind and enhances the fruit of the vrat.' } },
    { title: { hi: 'व्रत-कथा श्रवण', en: 'Vrat-katha Shravan' }, what: { hi: 'उस व्रत की कथा श्रद्धापूर्वक सुनें/पढ़ें; परिवार सहित हाथ में अक्षत लेकर कथा-श्रवण करें व अंत में अक्षत देव को अर्पित करें।', en: 'Hear/read the vrat\'s katha with devotion; the family holds akshat in hand while listening and offers it to the deity at the end.' }, why: { hi: 'कथा-श्रवण के बिना व्रत अपूर्ण माना जाता है; यह व्रत का माहात्म्य बताता है।', en: 'A vrat is deemed incomplete without hearing the katha; it reveals the vrat\'s glory.' } },
    { title: { hi: 'व्रत-नियम पालन', en: 'Observing the Niyam' }, what: { hi: 'दिनभर संयम रखें — निर्जल/फलाहार/एक-भुक्त अनुसार आहार लें; केवल सेंधा नमक, फल, दूध व व्रत-अन्न ग्राह्य; अन्न (चावल/गेहूँ) व सामान्य नमक त्याज्य।', en: 'Keep restraint all day — eat per nirjala/phalahar/ek-bhukt; only rock salt, fruit, milk and vrat-grains are allowed; grains (rice/wheat) and common salt are avoided.' }, why: { hi: 'आहार व इंद्रिय-संयम ही व्रत की आत्मा है।', en: 'Restraint of food and the senses is the very soul of the vrat.' } },
    { title: { hi: 'संध्या पूजन, आरती व दान', en: 'Evening Puja, Aarti & Daana' }, what: { hi: 'संध्या को पुनः देव-पूजन व आरती करें; भोग अर्पित कर यथाशक्ति ब्राह्मण/ज़रूरतमंद को दान करें।', en: 'In the evening worship the deity again and perform aarti; offer bhog and give daana to a brahmin/the needy as per capacity.' }, why: { hi: 'आरती व दान से व्रत का पुण्य पूर्ण होता है।', en: 'Aarti and daana complete the merit of the vrat.' } },
    { title: { hi: 'पारण (व्रत का समापन)', en: 'Paran (Breaking the Fast)' }, what: { hi: 'पंचांग-निर्धारित पारण-काल में ही व्रत तोड़ें — पहले देव को भोग व जल अर्पित कर, तुलसी/चरणामृत लेकर सात्त्विक भोजन से पारण करें (एकादशी: द्वादशी को हरि-वासर बाद; करवा चौथ: चंद्र-दर्शन बाद)।', en: 'Break the fast only in the panchang-fixed paran window — first offer bhog and water to the deity, then take tulsi/charanamrit and break with sattvic food (Ekadashi: on Dwadashi after Hari-Vasara; Karva Chauth: after sighting the moon).' }, why: { hi: 'गलत समय पर पारण व्रत का फल नष्ट कर देता है; सही पारण अनिवार्य है।', en: 'Paran at the wrong time destroys the vrat\'s fruit; correct paran is essential.' } },
    { title: { hi: 'उद्यापन (व्रत की पूर्णाहुति)', en: 'Udyapan (Concluding the Vrat)' }, what: { hi: 'नियत संख्या (जैसे 16 सोमवार, 16 शुक्रवार) पूर्ण होने पर उद्यापन करें — हवन, ब्राह्मण-भोज, कन्या/ब्राह्मण-पूजन व दान से व्रत को विधिवत समाप्त करें।', en: 'On completing the set number (e.g. 16 Mondays, 16 Fridays), perform the udyapan — conclude the vrat properly with a havan, brahmin-bhoj, kanya/brahmin-pujan and daana.' }, why: { hi: 'उद्यापन के बिना दीर्घ-व्रत अपूर्ण माने जाते हैं; यह व्रत की पूर्णाहुति है।', en: 'Long vrats are deemed incomplete without udyapan; it is the sealing oblation of the vrat.' } },
  ],
  mantras: [
    { title: { hi: 'गणेश वंदना', en: 'Ganesha Vandana' }, sanskrit: 'वक्रतुण्ड महाकाय सूर्यकोटि समप्रभ।\nनिर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥\nॐ गं गणपतये नमः॥', roman: 'Vakratunda Mahakaya Suryakoti Samaprabha.\nNirvighnam kuru me deva sarvakaryeshu sarvada.\nOm Gam Ganapataye Namah.', meaning: { hi: 'हे वक्रतुंड, महाकाय, करोड़ों सूर्य के समान तेजस्वी देव! मेरे सभी कार्य सदा निर्विघ्न पूर्ण करें।', en: 'O curved-trunk, mighty, radiant as a million suns — make all my tasks ever free of obstacles.' }, when: { hi: 'सबसे पहले, व्रत-पूजन के आरंभ में', en: 'First of all, at the start of the vrat-puja' }, count: '3 / 11' },
    { title: { hi: 'व्रत संकल्प मंत्र', en: 'Vrat Sankalp Mantra' }, sanskrit: 'ॐ विष्णुर्विष्णुर्विष्णुः, अद्य ब्रह्मणोऽह्नि द्वितीये परार्धे\nश्वेतवाराहकल्पे वैवस्वतमन्वन्तरे कलियुगे प्रथमचरणे\nमम आत्मनः श्रुतिस्मृतिपुराणोक्तफलप्राप्त्यर्थं\n(व्रत-नाम) व्रतम् अहं करिष्ये॥', roman: 'Om Vishnur Vishnur Vishnuh, adya Brahmano\'hni dvitiye parardhe\nshveta-varaha-kalpe vaivasvata-manvantare kaliyuge prathama-charane\nmama atmanah shruti-smriti-puranokta-phala-praptyartham\n(vrat-nama) vratam aham karishye.', meaning: { hi: 'तीन बार विष्णु-स्मरण कर, वर्तमान काल (कल्प, मन्वंतर, युग) का उच्चारण करते हुए मैं अपनी आत्मा के कल्याण व शास्त्रोक्त फल की प्राप्ति हेतु (अमुक) व्रत का संकल्प लेता/लेती हूँ।', en: 'Remembering Vishnu thrice and stating the present epoch (kalpa, manvantara, yuga), I resolve to observe the (named) vrat for the welfare of my soul and the fruit ordained by the scriptures.' }, when: { hi: 'व्रत आरंभ में संकल्प के समय', en: 'At the sankalp when beginning the vrat' } },
    { title: { hi: 'विष्णु मंत्र (एकादशी आदि)', en: 'Vishnu Mantra (Ekadashi etc.)' }, sanskrit: 'ॐ नमो भगवते वासुदेवाय॥', roman: 'Om Namo Bhagavate Vasudevaya.', meaning: { hi: 'भगवान वासुदेव (श्रीविष्णु) को नमस्कार — मोक्ष व सर्व-मंगल का द्वादशाक्षर मंत्र।', en: 'Salutations to Lord Vasudeva (Vishnu) — the twelve-syllable mantra of liberation and all auspiciousness.' }, when: { hi: 'विष्णु/एकादशी व्रत में जप', en: 'Japa in Vishnu/Ekadashi vrats' }, count: '108' },
    { title: { hi: 'शिव मंत्र (सोमवार/प्रदोष)', en: 'Shiva Mantra (Monday/Pradosh)' }, sanskrit: 'ॐ नमः शिवाय॥\nॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।\nउर्वारुकमिव बन्धनान् मृत्योर्मुक्षीय मामृतात्॥', roman: 'Om Namah Shivaya.\nOm tryambakam yajamahe sugandhim pushti-vardhanam.\nUrvarukam iva bandhanan mrityor mukshiya maamritat.', meaning: { hi: 'शिव को नमस्कार। हम त्रिनेत्र शिव का पूजन करते हैं; जैसे पका ककड़ी बेल से सहज छूट जाती है, वैसे हमें मृत्यु के बंधन से मुक्त कर अमरता दें।', en: 'Salutations to Shiva. We worship the three-eyed Shiva; as the ripe cucumber is freed from its stem, so free us from the bondage of death into immortality.' }, when: { hi: 'शिव/सोमवार/प्रदोष व्रत में जप', en: 'Japa in Shiva/Monday/Pradosh vrats' }, count: '108' },
    { title: { hi: 'हनुमान/शनि प्रार्थना', en: 'Hanuman/Shani Prayer' }, sanskrit: 'मनोजवं मारुततुल्यवेगं जितेन्द्रियं बुद्धिमतां वरिष्ठम्।\nवातात्मजं वानरयूथमुख्यं श्रीरामदूतं शरणं प्रपद्ये॥', roman: 'Manojavam maruta-tulya-vegam jitendriyam buddhimatam varishtham.\nvatatmajam vanara-yutha-mukhyam shri-rama-dutam sharanam prapadye.', meaning: { hi: 'मन के समान वेगवान, वायु-तुल्य गतिवाले, जितेन्द्रिय, बुद्धिमानों में श्रेष्ठ, पवनपुत्र, वानर-सेना के मुखिया श्रीराम-दूत हनुमान की मैं शरण लेता हूँ।', en: 'Swift as thought, fleet as the wind, master of the senses, foremost of the wise, son of the wind-god, chief of the vanara host, Shri Rama\'s messenger — Hanuman, I take refuge in you.' }, when: { hi: 'मंगल/शनि व्रत व संकट-निवारण हेतु', en: 'In Tuesday/Saturday vrats and for relief from troubles' } },
    { title: { hi: 'पारण / क्षमा प्रार्थना', en: 'Paran / Kshama Prayer' }, sanskrit: 'ॐ अज्ञानाद् यदि वा ज्ञानाद् व्रतैतत् कृतवानहम्।\nतस्य सांगत्वमायातु प्रसीद परमेश्वर॥\nॐ विष्णवे नमः — इदं व्रतफलं समर्पयामि॥', roman: 'Om ajnanad yadi va jnanad vratait kritavan aham.\ntasya sangatvam ayatu praseeda parameshvara.\nOm Vishnave namah — idam vrata-phalam samarpayami.', meaning: { hi: 'जाने-अनजाने जो व्रत मैंने किया, वह पूर्ण-सांग हो जाए; हे परमेश्वर, प्रसन्न होइए। विष्णु को नमन — यह व्रत-फल आपको समर्पित करता/करती हूँ।', en: 'Whatever vrat I have done, knowingly or unknowingly, may it become whole and complete; be pleased, O Lord. Salutations to Vishnu — I dedicate this fruit of the vrat to you.' }, when: { hi: 'पारण व व्रत-समर्पण के समय', en: 'At the paran and dedication of the vrat' } },
  ],
  aartis: [
    { title: { hi: 'ॐ जय जगदीश हरे', en: 'Om Jai Jagdish Hare' }, lines: 'ॐ जय जगदीश हरे, स्वामी जय जगदीश हरे।\nभक्त जनों के संकट, क्षण में दूर करे॥' },
    { title: { hi: 'व्रत-देव की आरती', en: 'Aarti of the Vrat-deity' }, lines: '(व्रत-देव अनुसार आरती गाएँ — शिव: "जय शिव ओंकारा"; हनुमान: "आरती कीजै हनुमान लला की"; देवी: "जय अम्बे गौरी"।)' },
  ],
  dos: [
    { hi: 'व्रत से पूर्व स्पष्ट संकल्प लें व पंचांग से पारण-समय अवश्य देख लें।', en: 'Take a clear sankalp before the vrat and be sure to check the paran time from the panchang.' },
    { hi: 'प्रातः स्नान कर सात्त्विक रहें; व्रत-कथा श्रद्धा से सुनें व मंत्र-जप करें।', en: 'Bathe in the morning and stay sattvic; hear the vrat-katha with devotion and do the japa.' },
    { hi: 'फलाहार में सेंधा नमक, फल, दूध व व्रत-अन्न ही लें; जल-सेवन (यदि निर्जल न हो) करते रहें।', en: 'In phalahar take only rock salt, fruit, milk and vrat-grains; keep drinking water (unless it is nirjala).' },
    { hi: 'सही समय पर देव को भोग अर्पित कर, दान करके ही पारण करें।', en: 'Break the fast (paran) only after offering bhog to the deity at the right time and giving daana.' },
  ],
  donts: [
    { hi: 'व्रत में अन्न (चावल/गेहूँ), सामान्य नमक, लहसुन-प्याज व तामसिक भोजन न लें।', en: 'Do not take grains (rice/wheat), common salt, garlic-onion or tamasic food during a vrat.' },
    { hi: 'क्रोध, झूठ, निंदा, हिंसा व दिन में शयन से बचें — व्रत केवल भूख का नाम नहीं।', en: 'Avoid anger, lies, slander, violence and sleeping in the day — a vrat is not merely hunger.' },
    { hi: 'गलत/मनमाने समय पर पारण न करें; इससे व्रत का फल नष्ट होता है।', en: 'Do not break the fast at a wrong/arbitrary time; it destroys the vrat\'s fruit.' },
    { hi: 'व्रत का दिखावा या केवल वज़न-घटाने की भावना से व्रत न रखें।', en: 'Do not keep a vrat for show or merely with the intent of losing weight.' },
  ],
  mistakes: [
    { hi: 'संकल्प लिए बिना व्रत आरंभ कर देना, जिससे व्रत अपूर्ण रह जाता है।', en: 'Starting the vrat without a sankalp, leaving it incomplete.' },
    { hi: 'पारण-समय की अनदेखी — एकादशी का पारण द्वादशी में न करना या करवा चौथ में चंद्र-दर्शन से पूर्व खा लेना।', en: 'Ignoring the paran time — not doing the Ekadashi paran within Dwadashi, or eating before moon-sighting in Karva Chauth.' },
    { hi: 'व्रत-कथा श्रवण, आरती व दान/उद्यापन को छोड़ देना।', en: 'Skipping the vrat-katha, aarti and the daana/udyapan.' },
  ],
  faqs: [
    { q: { hi: 'व्रत में क्या खा सकते हैं?', en: 'What can I eat during a vrat?' }, a: { hi: 'फलाहार में फल, दूध-दही, व्रत-अन्न (साबूदाना, कुट्टू, सिंघाड़ा, आलू) व सेंधा नमक ग्राह्य; निर्जल व्रत में जल भी नहीं लिया जाता।', en: 'In phalahar, fruit, milk-curd, vrat-grains (sabudana, kuttu, singhara, potato) and rock salt are allowed; in a nirjala vrat even water is not taken.' } },
    { q: { hi: 'पारण का सही समय कैसे जानें?', en: 'How do I know the correct paran time?' }, a: { hi: 'पंचांग/ऐप के मुहूर्त-अनुभाग में हर व्रत का पारण-काल दिया होता है; एकादशी का पारण द्वादशी को हरि-वासर के बाद व सूर्योदय-पश्चात करें।', en: 'The paran time for each vrat is given in the panchang/app\'s muhurat section; break the Ekadashi vrat on Dwadashi after the Hari-Vasara and after sunrise.' } },
    { q: { hi: 'निर्जल व फलाहार व्रत में क्या अंतर है?', en: 'What is the difference between nirjala and phalahar vrat?' }, a: { hi: 'निर्जल में जल-अन्न कुछ नहीं लिया जाता (कठोर); फलाहार में फल, दूध व व्रत-अन्न लेते हैं। स्वास्थ्यानुसार चुनें।', en: 'In nirjala nothing — not even water — is taken (strict); in phalahar fruit, milk and vrat-grains are allowed. Choose per your health.' } },
    { q: { hi: 'क्या रोगी, गर्भवती या बुज़ुर्ग व्रत रख सकते हैं?', en: 'Can the sick, pregnant or elderly keep a vrat?' }, a: { hi: 'शास्त्र स्वास्थ्य को प्राथमिकता देते हैं — ऐसे व्यक्ति फलाहार/एक-भुक्त या केवल देव-स्मरण से व्रत रख सकते हैं; कठोर निर्जल आवश्यक नहीं।', en: 'The shastras prioritise health — such persons may keep a phalahar/ek-bhukt vrat or simply remember the deity; a strict nirjala fast is not required.' } },
    { q: { hi: 'उद्यापन क्यों ज़रूरी है?', en: 'Why is udyapan necessary?' }, a: { hi: 'नियत संख्या के दीर्घ-व्रत (जैसे 16 सोमवार) उद्यापन से विधिवत पूर्ण होते हैं — इसके बिना व्रत अधूरा माना जाता है।', en: 'Long vrats of a set count (e.g. 16 Mondays) are properly completed by the udyapan — without it the vrat is deemed incomplete.' } },
    { q: { hi: 'यदि व्रत बीच में टूट जाए तो?', en: 'What if the vrat breaks midway?' }, a: { hi: 'अनजाने भंग होने पर क्षमा-प्रार्थना कर, अगली तिथि/अवसर पर पुनः व्रत रखें; श्रद्धा व संकल्प की शुद्धता सर्वोपरि है।', en: 'If broken unknowingly, offer the kshama-prarthana and keep the vrat again on the next tithi/occasion; purity of devotion and sankalp matters most.' } },
  ],
  estTime: { hi: 'दिनभर का संयम · पूजन ~30–60 मिनट', en: 'Day-long restraint · puja ~30–60 min' },
  difficulty: { hi: 'सरल–मध्यम · संकल्प व संयम आवश्यक', en: 'Easy–moderate · needs sankalp & restraint' },
  disclaimer: {
    hi: 'यह किसी भी व्रत की सामान्य वैदिक विधि है; हर व्रत के अपने विशिष्ट नियम, देव, कथा, तिथि व पारण-काल होते हैं जो क्षेत्र, परंपरा व कुलाचार अनुसार भिन्न होते हैं। स्वास्थ्य को प्राथमिकता दें; सटीक विधि, नियम व पारण-समय के लिए योग्य पुरोहित/आचार्य का परामर्श सर्वोपरि है।',
    en: 'This is the general Vedic method for any vrat; each vrat has its own specific rules, deity, katha, tithi and paran window that vary by region, tradition and family lineage (kulachar). Prioritise health; for the exact vidhi, niyam and paran time, a qualified purohit\'s guidance is supreme.',
  },
};

